quests[59071] = { id = 59071, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neu Geweiht", description = "Wir haben alle Reagenzien für den Gegenfluch!\n\nBeeilt Euch und wirkt ihn, bevor Qadarins Seele für immer verloren ist und Thiernax Euch nicht mehr helfen will und Tyrande im Schlund ein grauenhaftes Ende findet und alle traurig sind!\n\nAber fühlt Euch bloß nicht unter Druck gesetzt.", sourceObjective = "Wirkt den Gegenfluch.", progress = "Ich... Ich kann Euch nicht genug danken.", completion = "Ohne Eure Hilfe wäre Qadarins Seele für immer verloren gewesen.\n\nM... Mir bleibt nur noch, im Gegenzug meine Hilfe anzubieten.", sourceObjectiveStatus = "unverified-source-field" }
quests[59076] = { id = 59076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Diener des Chaos", description = "An alle Geknechteten und ungewürdigt Schuftenden der Schattenlande: Die Zeit ist gekommen, sich zu erheben. Erhebt Euch und zeigt es den Fangzähnen, den Schwingen und den Knochenmännern! Zeigt es den Mittlern und den Bossmännern! Ich sage, wir machen uns selbständig!\n\nKommt zu unserem Geheimtreffen an der Klippe des Schicksals.\n\nAn alle ungeknechteten Kriegsherren, Schlundgänger und moralisch flexiblen, starken Einwohner: Wir heuern Leute für's Grobe an. Interessierte dürfen sich gerne bewerben.\n\nSagt es nicht den Ordnungshütern.", sourceObjective = "Nehmt am öffentlich verkündeten \"Geheimtreffen\" teil.", sourceObjectiveStatus = "unverified-source-field" }
quests[59087] = { id = 59087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verflixter Fuchs!", description = "Ihr! Ja, Ihr da!\n\nIch, Fanfarenhymne, brauche Eure Hilfe. Ja, ja, nehmt Euch ruhig einen Moment Zeit, um Euch in meinem Glanz zu sonnen.\n\n<Fanfarenhymne gewährt Euch einen Moment.>\n\nFertig? Gut. Ihr müsst für mich ein besonders lästiges Vulpinjunges fangen. Der Kleine ist geradezu barbarisch! Läuft hier ständig Amok, bringt alles durcheinander und stört meinen Schönheitsschlaf! Er benutzt einen Tarnzauber, um unsichtbar zu bleiben, aber ich weiß genau, dass er es ist!\n\nMacht Euch mal nützlich und fangt diesen jungen Flegel!", sourceObjective = "Findet und fangt Renny das Vulpinjunge.", progress = "Und? Habt Ihr es gefangen?", completion = "Ihr habt dieses freche Fellbündel wirklich erwischt?\n\nHa! Ich bin angenehm überrascht. Und jetzt her mit ihm. Wir gehen direkt zu seinen Eltern. Ich muss dem geschätzten Fürsten Renard mal so richtig die Meinung sagen. Auch wenn er zum Hofstaat gehört, ich bin viel zu unaussprechlich wichtig, um mich ständig mit diesem missratenen Sprössling herumzuärgern!", sourceObjectiveStatus = "unverified-source-field" }
quests[59120] = { id = 59120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renny der Vulpin", description = "<Das Vulpinjunge hüpft fröhlich auf Euch zu und seine Augen funkeln förmlich vor Schabernack.\n\nIhr seid wohl interessant. Interessant genug, dass Euch dieses Kind von Fürst Renard vom Hof des Winters begleiten will.\n\nWas könnte dabei schon schiefgehen?>", sourceObjective = "<Und ganz plötzlich ist es ein Kinderspiel, den kleinen Vulpin hochzuheben.\n\nRenny schenkt Euch ein unmissverständliches Grinsen. Das geht sicher gut... oder?>", sourceObjectiveStatus = "unverified-source-field" }
quests[59126] = { id = 59126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versorgungskette", description = "<Freund/Freundin>! Gerade könnte ich Eure Expertise gebrauchen.\n\nEiner unserer Konvois wurde in der Nähe angegriffen! Er transportierte wichtige Vorräte... und neue Waren, die ich verkaufen wollte! \n\nEs ist wichtig, nein, überlebenswichtig, dass wir so viel davon wie möglich zurückholen.\n\nAlso, seid Ihr bereit zum Aufbruch? Retten wir, was wir können!", sourceObjective = "Sichert das Gebiet und bergt Atticus' Vorratsliste und 10 Osseinkampfpanzer.", progress = "Habt Ihr die Gegenstände gefunden?", completion = "Atticus wird jede Woche eine Kiste mit überzähligen Vorräten beiseitestellen, falls Ihr sie brauchen solltet.", sourceObjectiveStatus = "unverified-source-field" }
quests[59130] = { id = 59130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Haus der Seuchen", description = "Das Haus der Seuchen fiel diesem Konflikt als Erstes zum Opfer. Wir dachten, ihnen sei eine bloße Unachtsamkeit zum Verhängnis geworden. Hätten wir die Wahrheit doch nur früher gekannt...\n\nDoch vielleicht ist nicht all ihr Wissen verloren. Vor Eurer Ankunft meldeten unsere Späher Bewegungen bei den Ruinen ihrer Nekropole.\n\nFalls es Überlebende gibt, wäre es klug, sie bei uns aufzunehmen. Doch seien wir vorsichtig. Die Giftschäden könnten sie irre gemacht haben... oder noch Schlimmeres.", sourceObjective = "Sucht die Umgebung beim Haus der Seuchen nach Überlebenden ab.", completion = "Mein Lehrling! Ich habe überall nach Euch gesucht!", sourceObjectiveStatus = "unverified-source-field" }
quests[59147] = { id = 59147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hand der Läuterung", description = "Nikolon war nicht allein.\n\n<Eridia blickt mit finsterer Miene über die Tempelanlage.>\n\nSeit langer Zeit schon gebe ich alles für die Aspiranten in meiner Obhut. Seit langer Zeit habe ich für mein Paragon über diesen Tempel gewacht. Dass so viele gefallen sind, ganz allein, ist wirklich ein schwerer Schlag.\n\nAber diese... mutwillige Zerstörung! Das muss ein Ende haben.\n\nIhr seid mein Zorn, {name}. Meine strafende Hand. Geht. Vernichtet sie. Jeden Einzelnen.\n\nIch muss mich um jene kümmern, die noch übrig sind. Das ist meine oberste Pflicht. Sobald der Weg frei ist, treffen wir uns in der Nähe der Brücke.", sourceObjective = "\"Läutert\" den Tempel der Reinheit, indem Ihr Feinde vernichtet.", completion = "Manche Schandflecken muss man mit Gewalt entfernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[59171] = { id = 59171, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beutet sie aus", description = "Ohne einen Vorrat an Anima kann ich meine Mission nicht fortsetzen.\n\nZum Glück waren die Totenbeschwörer in der Nähe so freundlich, ein wenig davon in ihren Maldrazitkristallen zu sammeln.\n\nBitte nehmt ihnen diese Kristalle ab. Sie könnten sich etwas sträuben, sich davon zu trennen, aber ich gehe davon aus, dass Ihr sehr überzeugend sein könnt.", sourceObjective = "Sammelt 3 Mal animageladenes Maldrazit.", progress = "Enttäuscht mich nicht.", completion = "Ja, damit kann ich etwas anfangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[59172] = { id = 59172, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krieg beruht auf Täuschung", description = "Es lohnt sich, mit Euch verbündet zu sein, {name}.\n\nMephiles ist in der Tat ein reicher Quell an Informationen für uns. Aber das Haus der Rituale verzeiht keinen Verrat. Er wird nicht sprechen.\n\nAber das spielt keine Rolle. Das Haus der Augen weiß, wie man Gefangenen Informationen entlockt... auch ohne den Gebrauch von Worten.\n\nPlatziert die aufgeladenen Kristalle um mich herum. Sie werden das Verhör vereinfachen.", sourceObjective = "Bereitet das Verhör von Mephiles dem Loyalen vor.", completion = "Draka mag unseren Meister vergessen, doch ich werde nicht ruhen, bis er gerächt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[59173] = { id = 59173, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[59174] = { id = 59174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[59175] = { id = 59175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die ewige Rache", description = "<Auf den Regalen liegen Hunderte weiterer Phylakterien in allen möglichen Formen und Größen.\n\nViele tragen Namen. In dieses hier ist der Name Mor'Bitan eingeätzt.\n\nLady Vashj wäre sicher daran interessiert.>", sourceObjective = "Bringt das Phylakterium von Mor'Bitan zurück zu Lady Vashj.", sourceObjectiveStatus = "unverified-source-field" }
quests[59179] = { id = 59179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tochter der Nachtkriegerin", description = "In meinen Träumen sehe ich viele Dinge. Elfenseelen, die im Schlund gefoltert werden. Eine Kriegerin der Nacht, die von Rachsucht zerfressen wird.\n\nUnd... die Zerstörung des Ardenwalds.\n\nDiese Visionen sind flüchtig... und vage. Aber ich glaube, Tyrande Wisperwind ist der Schlüssel dazu, die Nachtelfen und dieses Reich zu retten.\n\nShandris Mondfeder, Tyrandes Tochter, plagen ähnliche Träume.\n\nSie ist im Moment auf dem Weg zur Ewigen Stadt. Findet sie. Wenn jemand Zugang zu Tyrandes Herz finden kann, dann sie.", sourceObjective = "Findet Shandris Mondfeder in Oribos.", completion = "{name}? Endlich ein willkommener Anblick an diesem seltsamen Ort.\n\nVielleicht wisst Ihr bereits, dass ich gekommen bin, um nach meiner Mutter zu suchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[59181] = { id = 59181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Schlund", description = "Ich habe Tyrande nicht mehr gesehen, seit sie zur Eiskrone aufbrach... aber ich sehe sie in meinen Träumen. Sie schleicht durch eine alptraumhafte Landschaft, durchdrungen von der Macht der Nachtkriegerin.\n\nKein Sterblicher kann diese Macht lange halten. Ich erschaudere, wenn ich daran denke, was diese Macht meiner Minn'do angetan hat.\n\nHochlord Fordragon hat mir vom Schlund erzählt. Wenn Ihr wirklich bereits seine Schrecken gemeistert habt, dann bitte ich Euch, mich auch durch diese Schrecken zu führen.\n\nWir müssen Tyrande finden und sie überzeugen, den Zorn der Nachtkriegerin verrauchen zu lassen.", sourceObjective = "Bringt Shandris Mondfeder in den Schlund.", completion = "In meinen Träumen habe ich Fragmente dieses finsteren Reichs gesehen. Tyrande hält sich dort auf.\n\nWir müssen sie finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[59183] = { id = 59183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treibender Kummer" }
quests[59184] = { id = 59184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Borr-Geth" }
quests[59185] = { id = 59185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verlockende Falle", sourceObjective = "Sammelt 8 Gefäße mit Maldrazitstaub.", progress = "Ich warte.", completion = "Dieses Mal entkommt er nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[59188] = { id = 59188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerühmte Vergeltung", description = "Ihr stammt also aus der Heimatwelt meiner Baronin? Sie muss sehr besonders sein, um solch mächtige Individuen hervorzubringen.\n\nDie Totenbeschwörer haben bereits mit den Vorbereitungen für Mor'Bitans Ritual begonnen. Wir sollten von ihrem Fortschritt profitieren. \n\nDrei Totenbeschwörer fungieren als die Architekten des Rituals. Wenn wir ihre Entwürfe hätten, könnten wir sie für unsere Zwecke anpassen.\n\nSammelt die Pläne... und ergötzt Euch ruhig an den Qualen Eurer Opfer.", sourceObjective = "Sammelt Ritualentwürfe der drei Architekten.", progress = "Wir hoffen auf Euren Erfolg.", completion = "Ja... Sie sollen von unserem Leid erfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[59189] = { id = 59189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Errettung von Tyrande Wisperwind", description = "Die Macht der Nachtkriegerin zerreißt Tyrande innerlich. Diese Wut... Sie wird von ihr aufgefressen.\n\n<Shandris schweigt einen Moment.>\n\nUnd doch spricht meine Mutter die Wahrheit. Wir können die Seelen meines Volks nicht einfach leiden lassen.\n\nWir werden Tyrande nach Torghast folgen. Wir müssen irgendwie die Geister der Kaldorei retten.\n\nUnd betet, dass wir dabei auch meine Minn'do retten können.", sourceObjective = "Betretet Torghast, um Tyrande Wisperwind zu retten.", completion = "Ich kann meiner Mutter ihre Absicht nicht verdenken... Aber sie wird komplett verschlungen werden, bevor sie Gerechtigkeit für unser Volk findet.\n\nWir müssen einen anderen Weg finden, um sie zurückzuholen.", sourceObjectiveStatus = "unverified-source-field" }
quests[59190] = { id = 59190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seht dem Tod ins Auge", description = "Ich verstehe, warum Draka Euch geschickt hat: Ihr erreicht, was sie nicht konnte.\n\nWir haben alle Teile. Jetzt müssen wir sie nur zusammensetzen.\n\nDie Schritte zum Ritual sind einfach: Platziert unsere frakturierten Kristalle in Formation um den Obelisk herum.\n\nDann kommt das Siegel. Unser Siegel. Benutzt das Maldrazitpulver, um eine bindende Glyphe am Sockel des Obelisken zu formen.\n\nKehrt zu mir zurück, wenn Ihr fertig seid.", sourceObjective = "Bereitet das Ritual vor.", completion = "Die Rache ist fast unser.", sourceObjectiveStatus = "unverified-source-field" }
quests[59196] = { id = 59196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geht und dient", description = "Wir dürfen nicht noch mehr Zeit verschwenden. Wir brauchen eine Audienz bei der Archon, bevor der nächste Angriff stattfindet!\n\nWir müssen einen Weg finden, um Euch zur Elysischen Feste zu bringen... und zwar schnell!\n\nDie Heldenrast ist ein Ort der Erholung für die Aspiranten der Bastion. Ihr könnt sie von jenseits der Felder dort oben schweben sehen.\n\nTrefft mich dort, sobald Ihr könnt. Ich habe einen Plan.", sourceObjective = "Trefft Kleia an der Heldenrast.", completion = "Der Polemarch? Er ist die rechte Hand der Archon!\n\nSie glaubt uns wirklich. Wir haben immer noch eine Chance!", sourceObjectiveStatus = "unverified-source-field" }
quests[59197] = { id = 59197, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Provost bei der Arbeit", description = "Provosten sind aus vielen Gründen nützlich.\n\nSie halten die Bastion sauber, reparieren alles, was kaputt ist, und bieten unübertroffene Gesellschaft und Unterstützung.\n\nEuer neuer Provostassistent sollte in der Lage sein, das Leuchtfeuer zu reparieren. Dann könnt Ihr den Polemarch zur Heldenrast rufen.", sourceObjective = "Benutzt 'Provost beschwören', um das Leuchtfeuer der Anrufung zu reparieren und ruft dann Polemarch Adrestes damit herbei.", completion = "Kalisthene hat sich für Euch verbürgt, indem sie die Verwendung des Leuchtfeuers gestattet hat. Aus dem Grund habt Ihr meine Aufmerksamkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[59198] = { id = 59198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf schnellen Flügeln", description = "Unsere verehrte Archon hat beschlossen, Euch eine Audienz zu gewähren.\n\nEs ist Eure Pflicht, ihr Eure Erkenntnisse zu präsentieren und dann ihrem weisen Urteil zu folgen.\n\nSie hält Audienz in der Elysischen Feste, einem Teil der Spitzen des Aufstiegs und Heimat der Aufgestiegenen.\n\nWir werden Euch dorthinbringen, denn es ist ein Ort für diejenigen, die fliegen können.", sourceObjective = "Fliegt mit Adrestes zur Elysischen Feste.", completion = "Die Gemächer der Archon sind direkt über uns. Ich ersuche Euch dringend, in ihrer Gegenwart äußerst ehrerbietig zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[59199] = { id = 59199, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kyrestia die Erstgeborene", description = "Ich werde Euch zu Eurer Audienz bei der Archon begleiten.\n\nIch bitte Euch, tragt Eure Informationen kurz und bündig vor.\n\nUnsere weise Archon wird Euch anhören und dann über das beste Vorgehen entscheiden.", sourceObjective = "Sprecht mit Adrestes, um das Wort an die Archon zu richten.", progress = "Niemand darf Zweifel an der Archon in ihrer unendlichen Weisheit hegen.", completion = "Die Gnade der Archon sei mit Euch, Sterblicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[59200] = { id = 59200, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schutze der Bastion", description = "Jeder Tempel der Bastion wird durch einen Schutz hier in der Elysischen Feste gesichert. Solange diese Schutze halten, kann keine bösartige Macht angreifen.\n\nEs ist alarmierend, dass die Verschmähten in solch großer Zahl angreifen konnten...\n\nEure Befehle lauten, die Schutze zu untersuchen. Solange sie halten, bleibt die Bastion stark.", sourceObjective = "Untersucht die Tempelschutze in der Elysischen Feste.", progress = "Die Schutze sichern jeweils einen der Tempel der Bastion. Wenn ein Schutz nicht aktiv ist, ist dieser Tempel angreifbar.", completion = "Offenbar befinden die Verschmähten sich in unserer Mitte, sogar in den Spitzen.\n\nWir müssen eilends Hilfe zum Tempel des Mutes schicken.", sourceObjectiveStatus = "unverified-source-field" }
quests[59202] = { id = 59202, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unter den Auserwählten", description = "Es verbleibt nur eine Rune...\n\nWir sollten zum Haus der Auserwählten zurückkehren und Markgraf Krexus von unseren Fortschritten berichten.", sourceObjective = "Kehrt zum Haus der Auserwählten zurück.", completion = "Ich werde dafür sorgen, dass meine Soldaten Krexus die gebührende Ehre erweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[59203] = { id = 59203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein kleines Darlehen", description = "Ich betreibe eine Unzahl an Geschäften hier: Wetten, leistungsstärkende Mittel... alles, wofür Kunden zahlen.\n\nEinige dieser Kunden sind jedoch mit ihren Zahlungen im Verzug. Und ein Kunde, der nicht bezahlt, ist ein Kunde ohne Wert.\n\nBitte fordert sie auf, ihre Schulden zu begleichen. Ich vertraue darauf, dass Ihr wisst, was zu tun ist, wenn sie sich weigern.", sourceObjective = "Sammelt 6 Animaphiolen von den Besuchern der Arena.", progress = "Versucht nicht, mich um das zu betrügen, was mir zusteht. Ich werde es merken.", completion = "Ja, Ihr seid wertvoller, als ich zuerst dachte.", sourceObjectiveStatus = "unverified-source-field" }
quests[59206] = { id = 59206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worte des Primus", description = "Auch in seiner Abwesenheit ist die Weisheit des Primus unser Leitstern. Diese Nachricht wurde hier wohl für jemanden hinterlassen, der ihrer würdig ist.\n\n<Draka mustert Euch eindringlich.>\n\nIhr seid nach Maldraxxus gekommen, um den Grund für die Invasion der Bastion zu erfahren. Jetzt wisst Ihr um den Verrat in unseren eigenen Reihen. Und auch, dass es hier einige tapfere Seelen gibt, die all das Unrecht wiedergutmachen wollen.\n\nBerichtet Euren Verbündeten in Oribos, was Ihr gesehen habt. Sorgt dafür, dass die Warnung des Primus die Ewigen erreicht.\n\nEs wäre mir eine Ehre, erneut an Eurer Seite zu kämpfen, {name}.", sourceObjective = "Kehrt nach Oribos zurück.", completion = "Ich bin froh über Eure Rückkehr, Sterblicher.\n\nIch bete, dass Ihr den Ausbruch eines Kriegs zwischen der Bastion und Maldraxxus erfolgreich verhindern konntet.", sourceObjectiveStatus = "unverified-source-field" }
quests[59207] = { id = 59207, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entfesseltes Wissen", description = "Diese Verschmähten plündern die Artefakte aus Kalliopes Rast. Und noch schlimmer ist, dass sie viele Gelehrte des Schreins gefangen halten.\n\nIch fürchte, sie werden die Aspiranten verhören, um alles über die Artefakte zu erfahren, die in der zentralen Kammer des Schreins verwahrt werden.\n\nDie meisten konnten mit mir zusammen entkommen, aber Lano, Eratus und Tyrana sind noch nicht zurückgekehrt.", sourceObjective = "Befreit Kurator Lano, Bibliothekar Eratus und Historikerin Tyrana.", completion = "Wir versorgen bereits einige der Kyrianer, die Ihr befreit habt. Ich danke Euch für Eure Hilfe, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[59209] = { id = 59209, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstärkung der Rebellen", description = "<General Draven sieht sich um.>\n\nWir brauchen weitere Verstärkung.\n\nIch weiß, dass es hier zwei gibt, die der wahren Zielsetzung von Revendreth ausgesprochen treu ergeben sind. Die Furchthetzerin hat sie wegen ihrer Treue hier zurückgelassen, damit sie von der Animadürre dahingerafft werden.\n\nSie sind beide absolut in der Lage, uns bei unserer Mission zu helfen.\n\nNehmt diesen Animapflock und stärkt die beiden. Schickt sie zu mir, ich werde ihnen die Situation erklären.", sourceObjective = "Rekrutiert Wachhauptmann Boromod und Taktikerin Sakaa.", completion = "Unsere Reihen sind verstärkt. Unsere Überlebenschancen sehen ein klein wenig besser aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[59210] = { id = 59210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besudelte Kerne", description = "Der Lich erwartet eine Belohnung für seinen Angriff auf das Haus der Augen. Aber die Macht, nach der er strebt, wird sein Niedergang sein.\n\nWir werden unser Wissen über sein geheimes Ritual nutzen, um ihn aus dem Haus der Rituale herauszulocken.\n\nNehmt diese Kristalle, {name}. Ladet sie mit der Anima von Mor'Bitans getöteten Dienern auf.\n\nAber fügt ihnen erst Bruchstellen zu, damit sie zerspringen, wenn das Ritual kurz vor dem Abschluss steht... aber nicht, bevor Mor'Bitan glaubt, dass es begonnen hätte.\n\nDas ist der Zeitpunkt, an dem wir zuschlagen werden.", sourceObjective = "Zerbrecht die drei erschöpften Animakristalle und ladet sie dann mit verstorbenen morbiden Ritualisten auf.", completion = "Gut ausgeführt.", sourceObjectiveStatus = "unverified-source-field" }
quests[59211] = { id = 59211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergessenes Dorf" }
quests[59223] = { id = 59223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von einem anderen Namen", description = "Gute Arbeit, mein Lehrling! Unser Labor funktioniert wieder!\n\nJetzt brauchen wir noch eine letzte Zutat, um den Trank für Markgräfin Stradama fertigzustellen.\n\nIhr müsst zum Gewächshaus laufen. Ich habe einen Zweig Angstschatten kultiviert, der geerntet werden kann.\n\nIch werden die anderen Reagenzien vorbereiten, während Ihr unterwegs seid. Seid vorsichtig!", sourceObjective = "Sammelt Angstschattenextrakt für Marileths Trank.", progress = "Habt Ihr sie gefunden?", completion = "Kommt, mein Lehrling! Unsere Anstrengungen tragen gleich Früchte!", sourceObjectiveStatus = "unverified-source-field" }
quests[59229] = { id = 59229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gigantischer Sucher" }
quests[59230] = { id = 59230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dartanos, der Seelenschinder" }
quests[59231] = { id = 59231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unergründliche Macht", description = "Vergebt mir... Ich fühlte mich einen Moment lang etwas benommen! Aber Ihr habt es geschafft! Ihr habt den Trank hergestellt!\n\nIch bin so stolz auf Euch. Welche Freude Eure Arbeit unserer Markgräfin gemacht hat!\n\nWas für ein Lehrer wäre ich, würde ich Euch um Hilfe bitten und meine nicht im Gegenzug anbieten? Wenn Ihr Forschungen anzustellen habt, habt Ihr meine volle Unterstützung!\n\nLasst uns zum Labor gehen. Ich bin maßlos auf Eure Erfolge gespannt!", sourceObjective = "Trefft Marileth beim Sitz des Primus.", completion = "Ich sehe, Ihr habt also eine Art... neuen Verbündeten. Und es wurde eine neue Rune ermächtigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[59232] = { id = 59232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Lektion in Demut", description = "Habt Dank für Eure Dienste bei der Beseitigung der Anklägerin und dem Aufstieg des Obersten Kämmerers an ihre Stelle.\n\nDer grundlose Verrat der Anklägerin machte sie unwürdig und unpassend als Mitglied des Hofes der Ernter.\n\nUnd jetzt seht bitte, was mit Verrätern in Revendreth passiert.", sourceObjective = "Beobachtet das Richturteil über die Anklägerin.", progress = "Beobachtet bitte in Stille, Schlundgänger.", completion = "Ich bin gnädig und verständnisvoll.\n\nDie Anklägerin soll eine Chance erhalten, ihre Fehler zu bereuen und aus ihnen zu lernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[59233] = { id = 59233, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des Prinzen neue Krone", description = "Die Krone ist fertig. Ich betraue Euch mit der Aufgabe, sie sicher an Renathal zu übergeben.\n\nBeeilt Euch, {name}. Diese Macht lässt sich nicht lange geheim halten, und so mancher wird sie sich mit Gewalt holen wollen.\n\nIhr könnt mit dem Spiegel zurückkehren. Sobald Ihr angekommen seid, werde ich jemanden losschicken, der ihn zerstört.\n\nGute Reise, <Schlundgänger/Schlundgängerin>.", sourceObjective = "Liefert die Krone der Ernter bei Prinz Renathal in Sündensturz ab.", completion = "Ausgezeichnete Arbeit, {name}.\n\nMit dieser Krone kann ich die Magie der Ernter zu einer unaufhaltsamen Macht bündeln. Jetzt können wir unsere Mission fortsetzen und Revendreth retten. Als Zeichen meiner Dankbarkeit für all Eure Hilfe öffne ich unsere Waffenkammer für Euch. Bitte sucht Euch eine Belohnung aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[59234] = { id = 59234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlamasselmix" }
quests[59242] = { id = 59242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr neues Zuhause", description = "Es schmerzt mich, meine Mutter zurückzulassen... Doch die Seelen meines Volks müssen in Sicherheit gebracht werden.\n\nIch habe die Diener in Oribos von einem Ort namens Ardenwald sprechen hören. Ein Reich uralter Wälder, in dem die Geister der Natur schlummern.\n\nIhr kennt dieses Land gut, nicht wahr? Ich möchte seine Wunder mit eigenen Augen sehen.\n\nVielleicht wissen die Geister dort, wie man meine Minn'do vor der Macht der Nachtkriegerin retten kann.", sourceObjective = "Bringt Shandris Mondfeder und die geretteten Seelen der Nachtelfen zu Ysera beim Herz des Waldes im Ardenwald.", progress = "Ihr seid wieder da. Aber was ist mit den anderen?", completion = "Mein Herz droht bei dem Gedanken an Tyrande zu zerspringen. Die Macht der Nachtkriegerin gibt ihr die Kraft, gegen diese Monster zu kämpfen... sie wird sie aber auch verschlingen, wenn wir nichts unternehmen.\n\nShandris und ich werden einem... vielversprechenden Gerücht nachgehen. Ich werde Euch rufen, sobald ich mehr weiß.", sourceObjectiveStatus = "unverified-source-field" }
quests[59246] = { id = 59246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tochter der Nachtkriegerin", description = "In meinen Träumen sehe ich viele Dinge. Elfenseelen, die im Schlund gefoltert werden. Eine Kriegerin der Nacht, die von Rachsucht zerfressen wird.\n\nUnd... die Zerstörung des Ardenwalds.\n\nDiese Visionen sind flüchtig... und vage. Aber ich glaube, Tyrande Wisperwind ist der Schlüssel dazu, die Nachtelfen und dieses Reich zu retten.\n\nShandris Mondfeder, Tyrandes Tochter, plagen ähnliche Träume.\n\nSie ist im Moment auf dem Weg zur Ewigen Stadt. Findet sie. Wenn jemand Zugang zu Tyrandes Herz finden kann, dann sie.", sourceObjective = "Findet Shandris Mondfeder in Oribos.", completion = "Ich werde Euch vorerst vertrauen, {name}.\n\nDoch solltet Ihr mich verraten, sorge ich dafür, dass Ihr dieselben Qualen erfahrt wie ich.", sourceObjectiveStatus = "unverified-source-field" }
quests[59254] = { id = 59254, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampftechniken für Fortgeschrittene", description = "Alaria sagt, dass Stacheleber andere Mitglieder ihrer Expedition gefangen genommen hätten.\n\nMöglicherweise müssen wir in den Bau der Stacheleber eindringen. Das ist äußerst riskant, denn sie sind viel aggressiver und intelligenter als die Murlocs, die Ihr schon kennengelernt habt.\n\nIch muss sicher sein, dass ich Euch nicht in den Tod schicke. Es wird Zeit für einen letzten Übungskampf.", sourceObjective = "Übt mit Kapitänin Garrick.", completion = "Gut gemacht, {name}. Lasst uns mit Alaria sprechen und dann diese Stacheleber jagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[59256] = { id = 59256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Furchthetzerin", description = "Die Falle wurde aufgestellt, und die Furchthetzerin ist direkt hineingetappt.\n\nWie ich erwartet hatte, macht ihr Stolz sie selbst dem Offensichtlichen gegenüber blind. Haltet die Phiole bereit, die Ihr von mir bekommen habt. Sie könnte Euch in dem kommenden Kampf gute Dienste leisten.\n\nWenn Ihr bereit seid, lassen wir die Falle zuschnappen.", sourceObjective = "Sprecht mit der Anklägerin, um die Falle auszulösen. Tötet dann die Furchthetzerin und sammelt das Medaillon des Schreckens ein.", progress = "Die Furchthetzerin muss fallen.", completion = "Das Medaillon wird uns gute Dienste leisten. Aber unser Anführer fehlt, um es anzulegen.\n\nWir brauchen weitere Verbündete.", sourceObjectiveStatus = "unverified-source-field" }
quests[59258] = { id = 59258, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Heimat der Tirnenn", description = "Der Gehörnte Jäger ist nicht mehr hier. Aber ich weiß, wo er hingegangen ist.\n\nEr hat seine Beute zur Ältestenwehr im Westen verfolgt. Gerade diese Wälder sind in letzter Zeit gefährlich geworden, und wir werden im Moment von einfallenden Verschlingern heimgesucht.\n\nSie haben die Straßen zwischen hier und der Wehr überrannt. Ich werde Euch über die Brücke begleiten und dafür sorgen, dass Ihr zum Gehörnten Jäger gebracht werdet.", sourceObjective = "Kämpft Euch den Weg in die Tiefen von Tirna Scithe frei und findet den Gehörnten Jäger.", completion = "Also dann, sprechen wir über die Jagd.", sourceObjectiveStatus = "unverified-source-field" }
quests[59259] = { id = 59259, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der ewige Peiniger" }
quests[59262] = { id = 59262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gebrochene Schwingen", description = "Ihr helft mir? Wirklich? Toll!\n\nSeht mich an. Was bin ich?\n\nIch habe Schnabel, Federn, schuppige Zehen. Ich bin Vogel, ja?\n\nAber Vögel haben Flügel. Und ich habe Arme. Warum keine Flügel?\n\nIch bin defekt. Ich kann nicht fliegen.\n\nLarion in der Nähe, fliegt so anmutig. Ich muss ihre Schwingen aus der Nähe sehen!\n\nHelft Ihr mir?", sourceObjective = "Bringt KowalskosAriellas Schwinge.", progress = "Wenn ich eine Larionschwinge untersuchen kann, kann ich bestimmt lernen!", completion = "Perfekt! Sehe ich mir genau an.", sourceObjectiveStatus = "unverified-source-field" }
quests[59263] = { id = 59263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flugfedern", description = "Jetzt halten wir sie neben meinen Arm...\n\nSeht! Da, viele lange Federn außen an der Larionschwinge!\n\nUnd keine bei mir. Deshalb kann ich nicht fliegen!\n\nHmm. Ich werde viele Flugfedern für meine Flügel brauchen.\n\nHelft Ihr?", sourceObjective = "Bringt Kowalskos 100 Larionflugfedern.", progress = "Federn... So viele Federn...", completion = "Ja, das sind genug Federn, damit meine Arme Flügel werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[59265] = { id = 59265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neugierige Blicke", description = "Die Konstrukte würden den Kadaver unserer Nekropole einem neuen Zweck zuführen. Aber wir brauchen ihre Teile für unsere eigenen Vorhaben.\n\nSchicken wir diesen Aasgeiern eine Warnung.\n\nTötet die Konstrukte in unseren Trümmern. Reißt Ihnen die Augen aus dem Schädel. Ein deutliches Zeichen.\n\nSie werden die Dunkelheit wieder fürchten.", sourceObjective = "Sammelt 20 Augen des Verräters von Konstrukten in Akareks Tränen.", progress = "Ihr bietet Geschenke?", completion = "Ich sehe Feigheit in ihren Augen. Das habt Ihr gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[59291] = { id = 59291, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eroberungsbelohnung" }
quests[59292] = { id = 59292, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eroberungsbelohnung" }
quests[59293] = { id = 59293, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besondere Formel", description = "Ihr denkt wahrscheinlich, ich bin von Natur aus gebläht, aber es braucht Arbeit, um das anzustauen. Das kommt von einem hübschen Überzug aus Pockenauswüchsen.\n\nHelft mir, meinen Überzug aufzufrischen.\n\nBringt mich einfach nahe an die absorbierende Pocke, und ich ziehe die Auswüchse direkt von ihrer schleimigen Haut.", sourceObjective = "Helft Gasbeutel, Pockenauswüchse zu sammeln.", progress = "Habt Ihr bekommen, was er brauchte?", completion = "Er stinkt schon wieder? Na ja, wenigstens ist er glücklich. Wir eher weniger.", sourceObjectiveStatus = "unverified-source-field" }
quests[59311] = { id = 59311, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie man eine Glimmerfliege fängt", description = "Ja! Richtige Hilfsmittel gesammelt. Jetzt nur noch Glimmerfliegen sammeln!\n\nAnimadürre ist schlimmer in den nördlichen Teichen. Viele verhungernde Glimmerfliegen sind dort, wollen am dringendsten aus unseren Animyllisblüten trinken.\n\nLegt Blüten hin. Wenn die Glimmerfliegen dann trinken, macht Fäden dran! Dann kommt wieder zu mir.", sourceObjective = "Fangt 5 verhungernde Glimmerfliegen in den Schimmernden Becken und kehrt dann zu Kowalskos zurück.", completion = "<Kowalskos ist ganz aufgeregt.>\n\nUnglaublich! Hat funktioniert! Hoffentlich halten die mich auch in der Luft!", sourceObjectiveStatus = "unverified-source-field" }
quests[59314] = { id = 59314, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sündensturz", description = "Ich wusste, ich würde auf Euch zählen können. Die Wiederbelebung von Revendreth ist davon abhängig, dass wir Pakte mit jenen außerhalb unseres Reiches schmieden.\n\nDer Prinz hatte keinerlei Zweifel, dass Ihr uns unterstützen würdet. In Erwartung Eurer Ankunft hat er den Hof der Ernter einberufen.\n\nRenathal erwartet Euch in Sündensturz, wo Ihr dem Hof vorgestellt werden sollt.", sourceObjective = "Meldet Euch bei Prinz Renathal in Sündensturz.", completion = "Ich habe keine Sekunde an Euch gezweifelt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[59315] = { id = 59315, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hof der Ernter", description = "Partnerschaften wie unsere sind der Schlüssel zur Wiederbelebung von Revendreth.\n\nAls Ernter haben wir die Fähigkeit, unsere Macht auf Sterbliche auszuweiten, aber diese Entscheidung muss einstimmig getroffen werden. Aus diesem Grund hat sich der Hof versammelt und erwartet Eure Ankunft.\n\nLassen wir ihn nicht warten.", sourceObjective = "Tretet vor den Hof der Ernter und schwört Eure Treue.", progress = "Der Hof wird Euch ganz sicher willkommen heißen. Aber zuerst müsst Ihr vor den Erntern einen Eid ablegen.", completion = "Willkommen an unserem bescheidenen Hof, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[59316] = { id = 59316, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bindende Macht", description = "Das Seelenband zu anderen ist nicht untrennbar. Aber dennoch sollte man diesen Schritt nicht leichtfertig wagen.\n\nIhr werdet die Vergangenheit Eures Partners sehen, seine Hoffnungen, Ängste, Träume und auch seine Erinnerungen, sofern noch welche vorhanden sind. Ihr seid dann im wahrsten Sinne des Wortes Seelenverwandte.\n\nIst das Band erst geknüpft, wächst Eure Verbindung über die körperliche Ebene hinaus und stärkt Euch in vielerlei Hinsicht... nicht nur Eure Muskeln.", sourceObjective = "Schließt das Ritual der Seelenbindung ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[59317] = { id = 59317, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stärken des Bands", description = "Spürt Ihr es auch? Unserer Verbindung ist stärker, als ich es für möglich gehalten hätte.\n\nMir wurde gesagt, das Band werde mit der Zeit noch enger, aber dass wir auch die Möglichkeit hätten, diesen Prozess zu beschleunigen.\n\nSündensturz braucht unsere Stärke. Vielleicht ist es das Beste, wenn wir diese Methode jetzt zur Anwendung bringen.", sourceObjective = "Stärkt Euer Band mit Nadjia.", sourceObjectiveStatus = "unverified-source-field" }
quests[59319] = { id = 59319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Intensivierung unserer Anstrengungen", description = "Die Hauptaufgabe der Venthyr besteht darin, sicherzustellen, dass die Seelen sich von ihrem Stolz lösen, aber sie tragen auch die Verantwortung für andere Dinge.\n\nWir müssen uns außerhalb der Grenzen von Revendreth bewegen und sicherstellen, dass die Seelen der Schattenlande ihrem Schicksal zugeführt werden.\n\nLasst es mich anhand einer einfachen Aufgabe für Eure Begleiterin hier demonstrieren. Dies wird der erste von vielen Angriffen sein.", sourceObjective = "Untersucht den Befehlstisch und beginnt ein Abenteuer.", completion = "Die Mission wird ein voller Erfolg werden, daran habe ich keinen Zweifel.", sourceObjectiveStatus = "unverified-source-field" }
quests[59321] = { id = 59321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heiliger Pakt", description = "Unser Pakt steht für mehr als nur Abkommen und Versprechen. Wir verfügen auch über beträchtliche Macht. Und an dieser Macht wollen wir Euch mithilfe eines heiligen Rituals teilhaben lassen.\n\nWenn es abgeschlossen ist, werdet Ihr unsere Gaben mit Leichtigkeit zu nutzen wissen.", sourceObjective = "Trefft Prinz Renathal in der Ritualhalle im unteren Bereich des Sanktums.", completion = "Willkommen, ich muss zugeben, dass ich sehr gerne an diesem monumentalen Ereignis teilnehme.", sourceObjectiveStatus = "unverified-source-field" }
quests[59322] = { id = 59322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geteilte Seelen", description = "Die Macht der Ernter fließt durch Euren sterblichen Körper. Doch Ihr könntet über noch mehr Macht verfügen, wenn Ihr Eure Seele an eine andere bindet.\n\nDies birgt keine bekannten Risiken, sondern bietet viele Vorteile für beide daran beteiligten Seiten.\n\nDie Anklägerin wird den Vorgang überwachen. Trefft sie an der Schmiede der Bande, wenn Ihr bereit seid.", sourceObjective = "Sucht die Anklägerin in der Schmiede der Bande auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[59323] = { id = 59323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Animaerwachen", description = "Mithilfe dieses Rituals werdet Ihr unsere Gaben nutzen können.\n\nWir werden die Anima in Eurer Seele anregen und eine Macht zum Leben erwecken, die bis jetzt nur den Erntern vorbehalten war.\n\nNoch nie hat ein Sterblicher diesen Vorgang durchlaufen, aber mir wurde versichert, dass Ihr keinen Schaden nehmen werdet.", sourceObjective = "Nehmt am Ritual der Ernter teil.", progress = "Nehmt Euren Platz ein, wenn Ihr bereit seid.", completion = "Solange der Pakt Bestand hat, gilt das auch für unsere Macht.", sourceObjectiveStatus = "unverified-source-field" }
quests[59325] = { id = 59325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein standhafter Verbündeter", description = "Es gibt einiges zu tun, <Schlundgänger/Schlundgängerin>. Die Ernter werden ihre Macht nicht ohne einen Kampf aufgeben.\n\nIhr braucht starke Verbündete an Eurer Seite, die wissen, wie man in den Schattenlanden kämpft.\n\nIch will Euch zur Seite stehen. Zusammen werden wir dafür sorgen, dass Revendreth zu seiner wahren Vorsehung zurückfindet.", sourceObjective = "Schließt den Prozess der Seelenbindung mit General Draven ab.", completion = "Gemeinsam sind wir stärker.", sourceObjectiveStatus = "unverified-source-field" }
quests[59327] = { id = 59327, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ruinen der Rebellion", description = "Hier sind wir nun... in Sündensturz.\n\nDas Letzte, was ich sah, war, wie der Meister Prinz Renathal und sein treuestes Gefolge hier in einer Strafkolonne entlanggezerrt hat. Allerdings ist das hier ein verbotener Ort, der von Gerüchten und Geheimnissen umwoben ist. Ich habe gehört, dass dies einst die Werkstatt von Denathrius war, in der er sich dunklen Experimenten hingab.\n\nUnbedingt faszinierend, aber wir sind hier, um Renathal zu finden. Sucht dort unten, aber seid vorsichtig. Ich werde die Anklägerin benachrichtigen, damit sie mit so vielen Verbündeten wie möglich hierherkommt.", sourceObjective = "Durchkämmt Sündensturz nach Hinweisen auf Prinz Renathal.", completion = "Ich werde Euch den Kopf von den Schultern schlagen, wenn Ihr...\n\nWartet...\n\nIhr lebt noch? Das bedeutet, Ihr seid... der Schlundgänger?", sourceObjectiveStatus = "unverified-source-field" }
quests[59339] = { id = 59339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampftechniken für Fortgeschrittene", description = "Alaria sagt, dass Stacheleber die restlichen Mitglieder der Expedition gefangen genommen hätten... darunter auch meinen Sohn.\n\nMöglicherweise müssen wir in den Bau der Stacheleber eindringen. Das ist äußerst riskant, denn sie sind viel aggressiver und intelligenter als die Murlocs, die Ihr schon kennengelernt habt.\n\nIch muss sicher sein, dass ich Euch nicht in Euer Grab schicke. Es wird Zeit für ein letztes Sparring.", sourceObjective = "Übt mit Kapitänin Garrick.", completion = "Gut gemacht, {name}. Lasst uns mit Alaria sprechen und dann diese Stacheleber jagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[59340] = { id = 59340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gallaths Glocke" }
quests[59342] = { id = 59342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gebändigte Wildnis", description = "Als <Jäger/Jägerin> braucht Ihr ein verlässliches Tier als Begleiter... oder diese Stacheleber schlachten Euch ab.\n\nSobald Ihr bereit seid, werde ich Euch lehren, wie man so ein Wildtier zähmt. Dann ist es an der Zeit, dass Ihr Euch einen treuen Begleiter erwählt.", sourceObjective = "Lernt von Austin Haxwart, wie man Wildtiere zähmt. Setzt dann 'Wildtier zähmen' bei einem Tier in der Nähe ein.", completion = "Jetzt steht Euch ein treuer Gefährte zur Seite. Kümmert Euch gut um ihn, dann sorgt er auch für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[59343] = { id = 59343, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seelenverwandtschaft", description = "Mir ist klar geworden, dass wir beide wahre Seelenverwandte sind.\n\nEure standhafte Natur hat mich in Bann geschlagen und ich ertrage den Gedanken an ein Nachleben ohne Eure betörende Gegenwart einfach nicht mehr.\n\nLasst uns das Seelenband flechten und unsere Herzen und Seelen für immer miteinander verbinden.", sourceObjective = "Schließt das Ritual der Seelenbindung ab.", completion = "Dass unsere Seelen jetzt für immer miteinander verbunden sind, lässt mein Herz vor Freude springen.", sourceObjectiveStatus = "unverified-source-field" }
quests[59344] = { id = 59344, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renavyths Medaillon" }
quests[59345] = { id = 59345, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phantoriax' Kriegsschwert" }
quests[59346] = { id = 59346, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Indris Flöte" }
quests[59347] = { id = 59347, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Mönch, ein Fokus", description = "Ihr habt Euch gegen die Harpyien gut geschlagen, aber wir müssen alle noch stärker werden, wenn wir die nächste Bedrohung meistern wollen.\n\nAls Erstes brauchen wir einen ruhigen Ort für die Meditation, um uns zu sammeln.\n\nDie wahre Kraft eines Mönchs erwächst aus seinem Fokus. Konzentration ist einfach alles.\n\nKommt. Ich kenne so einen Ort.", sourceObjective = "Folgt Kee-La und meditiert mit ihr.", completion = "Irgendetwas ist anders an Euch, {name}. Dann wollen wir mal sehen, was es genau ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[59348] = { id = 59348, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Schwingen!", description = "Idee! Vielleicht bin ich zu schwer. Brauche vielleicht mehr Flügel!\n\nGlimmerfliegen haben schöne Flügel. Mit richtigem Köder und starkem Seil können wir sie vielleicht fangen.\n\nBitte bringt Animyllisblüten. Ihr Nektar ist köstlich für Glimmerfliegen und macht sie schläfrig!", sourceObjective = "Sammelt 10 Animyllisblüten.", progress = "Der Nektar der Animyllisblüte ist die Lieblingsleckerei der Glimmerfliegen vor dem Schlafengehen!", completion = "Ich mag diese Blüten. So ein einzigartiger Duft, ja?", sourceObjectiveStatus = "unverified-source-field" }
quests[59349] = { id = 59349, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein letztes Sparring", description = "Machen wir noch ein schnelles Sparring, bevor wir ins Lager zurückkehren, {name}.\n\nIch würde gern sehen, was Ihr alles auf dieser Insel gelernt habt.", sourceObjective = "Kämpft im Sparring mit Kee-La.", completion = "Es freut mich, dass Ihr und Kee-La Eure Techniken verfeinert habt. Wir brauchen all unsere Kraft, wenn wir die Oger zurückdrängen wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[59350] = { id = 59350, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gestalten eines Druiden", description = "Danke, dass Ihr mich gerettet habt, {name}. Erlaubt mir, Euch dafür bei Euren Studien des Druidentums zu helfen.\n\nIch habe die Gestalt eines Hirsches angenommen, um aus dieser Grube zu entkommen. Ich habe eine Idee, wie auch Ihr lernen könnt, das zu tun.\n\nFolgt mir. Ganz in der Nähe steht ein uralter Druidenstein. Lasst uns dort Zwiesprache mit der Natur halten.", sourceObjective = "Haltet Zwiesprache mit dem Druidenstein in der Nähe.", completion = "Gut! Ich spüre, wie der Segen der Geister Euch durchströmt.\n\nKonzentriert Euch. Dann solltet Ihr merken, dass Ihr eine neue Gestalt annehmen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[59351] = { id = 59351, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fäden finden", description = "Glimmerfliegen sind Kreaturen aus Anima. Sie sehen zart aus, sind aber echt stark!\n\nFäden vom Ätherwyrmschwanz sind stabil. Sie sollten helfen, Glimmerfliegen festzuhalten.\n\nSammelt sie für mich!", sourceObjective = "Sammelt 10 Ätherwyrmfäden.", progress = "Ätherwyrmfäden sind fast reine Anima. Sehr schwer zu zerreißen!", completion = "<Kowalskos zerrt mit aller Kraft an den Fäden.>\n\nSeht Ihr? Sehr stark!", sourceObjectiveStatus = "unverified-source-field" }
quests[59352] = { id = 59352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Wissen der Magier", description = "Auch wenn Ihr als <Magier/Magierin> noch grün hinter den Ohren seid... Hut ab. Vielleicht werdet Ihr ja eines Tages so gut wie ich!\n\nAber von 'Verwandlung' habt Ihr keinen Schimmer! Was soll das denn?\n\n'Verwandlung' ist einer der nützlichsten Zauber für jeden Magier. Aber ich kann es Euch beibringen, wenn Ihr mir mein Zauberbuch holt.\n\nDas letzte Mal hab ich es gesehen, als es die Oger in den See geworfen haben. In den SEE!\n\nBesorgt mir mein Buch und ich zeige Euch, wie man 'Verwandlung' wirkt.", sourceObjective = "Holt Meredy Weidmannsheils Buch vom Grund des nahe gelegenen Sees zurück.", progress = "Hoffentlich hat mein Buch nicht zu sehr darunter gelitten, am Grunde eines Sees zu liegen.", completion = "Perfekt! Mal sehen... Ah, die Seite für 'Verwandlung' ist noch lesbar!\n\nNa ja, ein paar Wörter fehlen, aber wenn man die Magie erst mal begreift, kann man das meiste überspringen.\n\nHier, ich bringe es Euch bei... und ich zeige Euch, wie es funktioniert!", sourceObjectiveStatus = "unverified-source-field" }
quests[59354] = { id = 59354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wozu Schäfchen doch gut sind", description = "Ich schicke Euch doch nicht einfach so in die Welt hinaus, ohne dass Ihr mal gesehen habt, was der Zauber alles kann.\n\n'Verwandlung' rettet Euch den Hintern, wenn Euch zwei Feinde gleichzeitig ans Leder wollen.\n\nCole und ich tun mit Euch mal so als ob. Dann sehen wir ja, ob Ihr wisst, was zu tun ist.", sourceObjective = "Übt 'Verwandlung' gegen Meredy und den Gefreiten Cole.", completion = "Ich glaub, Ihr habt den Bogen raus. Also wenn Ihr mal bis zum Hals drinsteckt, denkt an 'Verwandlung'.", sourceObjectiveStatus = "unverified-source-field" }
quests[59355] = { id = 59355, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Falle des Jägers", description = "Alle Jäger sollten bis jetzt eigentlich etwas über das Fallenstellen gelernt haben. Ich zeige Euch mal schnell, wie es geht.\n\nFangen wir mit einer Eiskältefalle an. Ihr müsst in der Umgebung Material sammeln, um eine zu machen.\n\nMeredy hat bestimmt ein Eispartikel. Für den Rest müsst Ihr Euch bloß hier in der Gegend umsehen.\n\nUnd nicht trödeln. Ihr werdet die Falle für das Problem brauchen, mit dem sich das Lager herumschlagen muss.", sourceObjective = "Sammelt Bestandteile in der Gegend, um eine Eiskältefalle zu bauen.", progress = "Habt Ihr alles besorgt? Meredy sollte das Eispartikel haben und die anderen zwei Sachen findet Ihr in der Nähe.", completion = "Mit etwas Arbeit wird daraus eine ganz brauchbare Falle.\n\nAls {class} müsst Ihr damit arbeiten, was die Umgebung hergibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[59356] = { id = 59356, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Jagd auf den Pirscher", description = "Nachdem Ihr jetzt eine Falle habt, kommen wir zu einem Problem, um das wir uns kümmern müssen.\n\nEin wildes Tier schleicht um unser Lager. Es hat schon etwas von unserem Proviant gestohlen. Wir haben ohnehin kaum etwas.\n\nWir beide arbeiten jetzt zusammen. Legt Eure Eiskältefalle aus und lockt hervor, was immer es sein mag.\n\nSobald es in der Falle ist, entscheide ich, ob wir das Tier zähmen können... oder es erlegen müssen.", sourceObjective = "Legt Eure Eiskältefalle in den Ogerruinen aus, um das wilde Tier herauszulocken, das um das Lager schleicht.", completion = "Danke für Eure Hilfe, {name}. Ich kann Euch noch eine letzte Sache beibringen. Ich zeige Euch, wie man einen anderen Begleiter ruft.\n\nAuf dieser Insel gibt es jede Menge wilde Tiere. Schaut doch mal, welche Ihr so zähmen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[59426] = { id = 59426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer persönlicher Assistent", description = "Hier in der Heldenrast haben wir ein Leuchtfeuer. Es ist der schnellste Weg, um die Aufmerksamkeit des Polemarchen zu erregen.\n\nEs ist allerdings einige Zeit her, seit wir es das letzte Mal benutzt haben. Daher bedarf es leider einiger Reparaturen.\n\nIch erteile Euch die Genehmigung, während Eures Aufenthalts in der Bastion einen Provostbegleiter zu erhalten.\n\nIch werde einige herbeirufen. Ihr dürft einen auswählen, der Euch hilft.", sourceObjective = "Wählt einen Provost aus, der Euch unterstützen soll, und kehrt dann zu Kalisthene zurück.", progress = "Provosten sind die Kraft, die die Bastion am Laufen halten.", completion = "Wenn Ihr Unterstützung benötigt, wird Euer Provost Euch mit vielfältigen Dienstleistungen zur Verfügung stehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[59427] = { id = 59427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir brauchen mehr Macht", description = "Laurents Vorhaben ist ehrgeizig.\n\nSpiegel sind am zuverlässigsten, wenn es um nahe Ziele geht. Eine Reise zum Refugium erfordert viel Macht... mehr als er oder ich haben.\n\nDie Verhüllten haben Animavorräte in ihrem Lager. Der Spiegel sollte mit genug davon ausreichend stabil sein, um uns ans Ziel zu bringen.", sourceObjective = "Sammelt Anima in der Verhüllten Zuflucht.", progress = "Reisen zu entfernten Zielen erfordern eine Menge Macht.", completion = "Ja, das wird reichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[59430] = { id = 59430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bräuche voller Seuche", description = "Obwohl das tatsächliche Haus der Seuchen verloren ist, ist es das Wissen darin nicht. Es gibt hier Überlebende, die weiter forschen und grauenerregende neue Waffen entwickeln. \n\nWir werden das Haus wieder aufbauen, noch größere Macht erlangen und bislang ungekannte Schöpfungen und Seuchen auf unsere Feinde loslassen!\n\nVielleicht könnt Ihr helfen? Sprecht mit Überlebenden und findet heraus, ob Ihr ihnen helfen könnt.", sourceObjective = "Sprecht mit Überlebenden des Hauses der Seuchen.", progress = "Habt Ihr mit jemandem gesprochen?", completion = "Von unserer Zusammenarbeit werden wir beide profitieren!", sourceObjectiveStatus = "unverified-source-field" }
quests[59441] = { id = 59441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seelenschmied Yol-Mattar" }
quests[59520] = { id = 59520, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seuchensturz: Knietief drin", description = "Viele vom Haus der Seuchen haben die Zerstörung überlebt, sind aber später an den durch die Explosion freigesetzten Seuchen zugrunde gegangen. Markgräfin Stradama selbst wurde von einer Mischung aus zwölf Arten luftübertragene Pocken in den Wahnsinn getrieben!\n\nDiese Gefahren sind immer noch vorhanden. Sie breiten sich von den Ruinen aus und infizieren täglich neue Opfer.\n\nIch möchte, dass Ihr die Ruinen aufsucht und von den Opfern dort Proben einsammelt.", sourceObjective = "Begebt Euch nach Seuchensturz und sammelt 12 Pockenhautproben sowie Markgräfin Stradamas Plasma.", progress = "Habt Ihr mir die Pockenhautproben gebracht?", completion = "Von unserer Zusammenarbeit werden wir beide profitieren!", sourceObjectiveStatus = "unverified-source-field" }
quests[59554] = { id = 59554, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine feierliche Reise", description = "Alle Aspiranten, alt wie neu, hört her! Agthias Ruhestätte erwartet Euch wie verkündet.\n\nBegebt Euch auf die zeremonielle Reise und erfahrt alles über das uralte gefallene Paragon, das dieses Reich gerettet hat!\n\nDie Ruhestätte befindet sich nur einen kurzen Ritt südwestlich der Heldenrast.", sourceObjective = "Sprecht mit Hüter Mnemis in Agthias Ruhestätte.", completion = "Was führt Euch zu unserer bescheidenen Stätte?", sourceObjectiveStatus = "unverified-source-field" }
quests[59555] = { id = 59555, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Feind auf der Schwelle", description = "Die übrigen Häuser von Maldraxxus haben sich gegen uns verschworen. Ihre Streitkräfte belagern den Sitz des Primus, und unsere Abwehr wird nicht ewig standhalten können.\n\nUnsere Reserveeinheiten kämpfen gegen den Feind. Ihr müsst die Belagerung brechen.\n\nMeldet Euch bei Heirmir und Marileth. Sie werden Euch ein Mittel geben, um Zerstörung auf unsere Feinde herabregnen zu lassen.", sourceObjective = "Reitet Zornschwinge und zerstört die feindlichen Streitkräfte.", completion = "Der Feind leckt seine Wunden! Unsere Truppen halten für den Moment die Stellung, aber wir sollten auf weitere Angriffe vorbereitet sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[59556] = { id = 59556, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen in unserem Haus", description = "Ich hatte aufgrund Eurer Beziehungen zu den anderen Pakten Bedenken, ob Ihr zurückkehren würdet. Aber das war offenbar töricht von mir.\n\nIhr seid zwar ein Fremdling, aber Ihr habt tapfer auf Seiten der Armeen von Maldraxxus gekämpft. Ich bin mir sicher, dass der Primus keine Bedenken hätte, Euch in unsere Reihen aufzunehmen.\n\nEines Tages kommt er womöglich sogar zurück. Aber wir können es uns nicht leisten, darauf zu warten.\n\nIn Abwesenheit des Primus ernenne ich Euch zu einem Nekrolord von Maldraxxus.", sourceObjective = "Sprecht mit Baronin Draka, um als Nekrolord in die Pakthalle von Maldraxxus eingeführt zu werden.", completion = "Dies ist unser Krieg und wir müssen ihn gewinnen, Schlundgänger. Aber jetzt ist es auch der Eure.", sourceObjectiveStatus = "unverified-source-field" }
quests[59578] = { id = 59578, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mut zur Demut" }
quests[59581] = { id = 59581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Stärke von Sündensturz" }
quests[59583] = { id = 59583, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen in Sturmwind", description = "Nachdem wir jetzt wieder in Sturmwind sind, muss ich König Wrynn meinen Missionsbericht überbringen.\n\nIch habe Lindie gebeten, Euch in der Zwischenzeit die Stadt zu zeigen. Es gibt in Sturmwind viel zu sehen und zu erleben, also nehmt Euch ruhig die Zeit, alles zu erkunden.\n\nIch werde nach Euch rufen lassen, sobald ich dem König meinen Bericht vorgestellt habe.", sourceObjective = "Trefft Euch mit Lindie Sprungfeder am Stadttor.", completion = "Hey, {name}! Schön, Euch zu sehen!\n\nKapitänin Garrick hat mich gebeten, Euch die Stadt zu zeigen. Ich freue mich schon sehr darauf!", sourceObjectiveStatus = "unverified-source-field" }
quests[59585] = { id = 59585, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir machen noch einen Aspiranten aus Euch" }
quests[59586] = { id = 59586, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist Eure Spezialität?", description = "Hey, {name}! Habt Ihr Euch schon für eine Kampfspezialisierung entschieden?\n\nAls {class} kennt Ihr ja schon die verschiedenen Klassen für Abenteurer. Aber habt Ihr gewusst, dass es bei jeder Klasse auch noch verschiedene Spezialisierungen gibt?\n\nWelche Spezialisierung man wählt, ist eine wichtige Entscheidung. Eure Spezialisierung bestimmt, welcher Platz Euch im Kampf in Eurer Gruppe zufällt, und auch, welche Waffen und Fähigkeiten Ihr einsetzt.\n\nKommt, sprechen wir mal mit Dalgrun Stahlkiefer über die Spezialisierungen!", sourceObjective = "Sprecht mit Dalgrun Stahlkiefer, um mehr über Kampfspezialisierungen zu erfahren.", progress = "Seid gegrüßt. Möchtet Ihr mehr über Kampfspezialisierungen erfahren?", completion = "Eine ausgezeichnete Wahl für Eure Spezialisierung, {name}.\n\nIhr dürft Eure neuen Fähigkeiten gern mal draußen an den Trainingsattrappen ausprobieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[59587] = { id = 59587, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist Eure Spezialität?", description = "Hey, {name}! Habt Ihr Euch schon für eine Kampfspezialisierung entschieden?\n\nAls {class} kennt Ihr ja schon die verschiedenen Klassen für Abenteurer. Aber habt Ihr gewusst, dass es bei jeder Klasse auch noch verschiedene Spezialisierungen gibt?\n\nWelche Spezialisierung man wählt, ist eine wichtige Entscheidung. Eure Spezialisierung bestimmt, welcher Platz Euch im Kampf in Eurer Gruppe zufällt, und auch, welche Waffen und Fähigkeiten Ihr einsetzt.\n\nKommt, sprechen wir mal mit Frodo Frostfinger über die Spezialisierungen!", sourceObjective = "Sprecht mit Frodo Frostfinger, um mehr über Kampfspezialisierungen zu erfahren.", progress = "Seid gegrüßt. Möchtet Ihr mehr über Kampfspezialisierungen erfahren?", completion = "Eine ausgezeichnete Wahl für Eure Spezialisierung, {name}.\n\nIhr dürft Eure neuen Fähigkeiten gern mal draußen an den Trainingsattrappen ausprobieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[59588] = { id = 59588, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist Eure Spezialität?", description = "Hey, {name}! Habt Ihr Euch schon für eine Kampfspezialisierung entschieden?\n\nAls {class} kennt Ihr ja schon die verschiedenen Klassen für Abenteurer. Aber habt Ihr gewusst, dass es bei jeder Klasse auch noch verschiedene Spezialisierungen gibt?\n\nWelche Spezialisierung man wählt, ist eine wichtige Entscheidung. Eure Spezialisierung bestimmt, welcher Platz Euch im Kampf in Eurer Gruppe zufällt, und auch, welche Waffen und Fähigkeiten Ihr einsetzt.\n\nKommt, sprechen wir mal mit Juisheng Halbkralle über die Spezialisierungen!", sourceObjective = "Sprecht mit Juisheng Halbkralle, um mehr über Kampfspezialisierungen zu erfahren.", completion = "Eine ausgezeichnete Wahl für Eure Spezialisierung, {name}.\n\nIhr dürft Eure neuen Fähigkeiten gern mal draußen an den Trainingsattrappen ausprobieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[59589] = { id = 59589, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist Eure Spezialität?", description = "Hey, {name}! Habt Ihr Euch schon für eine Kampfspezialisierung entschieden?\n\nAls {class} kennt Ihr ja schon die verschiedenen Klassen für Abenteurer. Aber habt Ihr gewusst, dass es bei jeder Klasse auch noch verschiedene Spezialisierungen gibt?\n\nWelche Spezialisierung man wählt, ist eine wichtige Entscheidung. Eure Spezialisierung bestimmt, welcher Platz Euch im Kampf in Eurer Gruppe zufällt, und auch, welche Waffen und Fähigkeiten Ihr einsetzt.\n\nKommt, sprechen wir mal mit Ezul'aan über die Spezialisierungen!", sourceObjective = "Sprecht mit Ezul'aan, um mehr über Kampfspezialisierungen zu erfahren.", progress = "Seid gegrüßt. Möchtet Ihr mehr über Kampfspezialisierungen erfahren?", completion = "Eine ausgezeichnete Wahl für Eure Spezialisierung, {name}.\n\nIhr dürft Eure neuen Fähigkeiten gern mal draußen an den Trainingsattrappen ausprobieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[59590] = { id = 59590, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist Eure Spezialität?", description = "Hey, {name}! Habt Ihr Euch schon für eine Kampfspezialisierung entschieden?\n\nAls {class} kennt Ihr ja schon die verschiedenen Klassen für Abenteurer. Aber habt Ihr gewusst, dass es bei jeder Klasse auch noch verschiedene Spezialisierungen gibt?\n\nWelche Spezialisierung man wählt, ist eine wichtige Entscheidung. Eure Spezialisierung bestimmt, welcher Platz Euch im Kampf in Eurer Gruppe zufällt, und auch, welche Waffen und Fähigkeiten Ihr einsetzt.\n\nKommt, sprechen wir mal mit Patrice Lancaster über die Spezialisierungen!", sourceObjective = "Sprecht mit Patrice Lancaster, um mehr über Kampfspezialisierungen zu erfahren.", completion = "Eine ausgezeichnete Wahl für Eure Spezialisierung, {name}.\n\nIhr dürft Eure neuen Fähigkeiten gern mal draußen an den Trainingsattrappen ausprobieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[59591] = { id = 59591, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist Eure Spezialität?", description = "Hey, {name}! Habt Ihr Euch schon für eine Kampfspezialisierung entschieden?\n\nAls {class} kennt Ihr ja schon die verschiedenen Klassen für Abenteurer. Aber habt Ihr gewusst, dass es bei jeder Klasse auch noch verschiedene Spezialisierungen gibt?\n\nWelche Spezialisierung man wählt, ist eine wichtige Entscheidung. Eure Spezialisierung bestimmt, welcher Platz Euch im Kampf in Eurer Gruppe zufällt, und auch, welche Waffen und Fähigkeiten Ihr einsetzt.\n\nKommt, sprechen wir mal mit Veruca Dunkelstrom über die Spezialisierungen!", sourceObjective = "Sprecht mit Veruca Dunkelstrom, um mehr über Kampfspezialisierungen zu erfahren.", completion = "Eine ausgezeichnete Wahl für Eure Spezialisierung, {name}.\n\nIhr dürft Eure neuen Fähigkeiten gern mal draußen an den Trainingsattrappen ausprobieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[59592] = { id = 59592, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist Eure Spezialität?", description = "Hey, {name}! Habt Ihr Euch schon für eine Kampfspezialisierung entschieden?\n\nAls {class} kennt Ihr ja schon die verschiedenen Klassen für Abenteurer. Aber habt Ihr gewusst, dass es bei jeder Klasse auch noch verschiedene Spezialisierungen gibt?\n\nWelche Spezialisierung man wählt, ist eine wichtige Entscheidung. Eure Spezialisierung bestimmt, welcher Platz Euch im Kampf in Eurer Gruppe zufällt, und auch, welche Waffen und Fähigkeiten Ihr einsetzt.\n\nKommt, sprechen wir mal mit Mulric Frechfels über die Spezialisierungen!", sourceObjective = "Sprecht mit Mulric Frechfels, um mehr über Kampfspezialisierungen zu erfahren.", completion = "Eine ausgezeichnete Wahl für Eure Spezialisierung, {name}.\n\nIhr dürft Eure neuen Fähigkeiten gern mal draußen an den Trainingsattrappen ausprobieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[59593] = { id = 59593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist Eure Spezialität?", description = "Hey, {name}! Habt Ihr Euch schon für eine Kampfspezialisierung entschieden?\n\nAls {class} kennt Ihr ja schon die verschiedenen Klassen für Abenteurer. Aber habt Ihr gewusst, dass es bei jeder Klasse auch noch verschiedene Spezialisierungen gibt?\n\nWelche Spezialisierung man wählt, ist eine wichtige Entscheidung. Eure Spezialisierung bestimmt, welcher Platz Euch im Kampf in Eurer Gruppe zufällt, und auch, welche Waffen und Fähigkeiten Ihr einsetzt.\n\nKommt, sprechen wir mal mit Laphandrus Leerenherz über die Spezialisierungen!", sourceObjective = "Sprecht mit Laphandrus Leerenherz, um mehr über Kampfspezialisierungen zu erfahren.", completion = "Eine ausgezeichnete Wahl für Eure Spezialisierung, {name}.\n\nIhr dürft Eure neuen Fähigkeiten gern mal draußen an den Trainingsattrappen ausprobieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[59594] = { id = 59594, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist Eure Spezialität?", description = "Hey, {name}! Habt Ihr Euch schon für eine Kampfspezialisierung entschieden?\n\nAls {class} kennt Ihr ja schon die verschiedenen Klassen für Abenteurer. Aber habt Ihr gewusst, dass es bei jeder Klasse auch noch verschiedene Spezialisierungen gibt?\n\nWelche Spezialisierung man wählt, ist eine wichtige Entscheidung. Eure Spezialisierung bestimmt, welcher Platz Euch im Kampf in Eurer Gruppe zufällt, und auch, welche Waffen und Fähigkeiten Ihr einsetzt.\n\nKommt, sprechen wir mal mit Kualiang Donnerfaust über die Spezialisierungen!", sourceObjective = "Sprecht mit Kualiang Donnerfaust, um mehr über Kampfspezialisierungen zu erfahren.", progress = "Seid gegrüßt. Möchtet Ihr mehr über Kampfspezialisierungen erfahren?", completion = "Eine ausgezeichnete Wahl für Eure Spezialisierung, {name}.\n\nIhr dürft Eure neuen Fähigkeiten gern mal draußen an den Trainingsattrappen ausprobieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[59596] = { id = 59596, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geteilte Seele", description = "Seelen in Maldraxxus sind durch den Krieg verbunden. Wir ziehen Kraft und Weisheit aus den anderen um uns herum.\n\nSolltet Ihr in der Schlacht fallen, würde ein Teil von Euch bei Euren Kameraden verbleiben, so wie auch sie bei Euch bleiben würden.\n\nSeuchenerfinder Marileth möchte Euch den Prozess der Seelenbindung lehren. Meiner bisherigen Erfahrung nach wird Euer Band ein starkes sein.", sourceObjective = "Sprecht mit Seuchenerfinder Marileth über den Prozess der Seelenbindung.", completion = "Ich bin so froh, Euch wiederzusehen, mein Lehrling!", sourceObjectiveStatus = "unverified-source-field" }
quests[59597] = { id = 59597, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einfach sympathisch", description = "Ein Seelenband einzugehen ist ein wundervoller Prozess! Ich lade Euch ein, Euch mit mir zu verbinden, um zu erlernen, wie es funktioniert, aber im Laufe der Zeit verbindet Ihr Euch sicher mit anderen. \n\nIch kannte viele Seelenbande, aber an erster Stelle steht Markgräfin Stradama! Ihr Wissen, Talent und ihre Güte wurden Teil von mir. Dieses Band teilen wir jetzt und für immer.\n\nIch hoffe nur, dass ich Euch nützlich sein kann. So teile ich alles mit Euch und helfe Euch auch, wenn wir nicht beisammen sind.", sourceObjective = "Schließt das Ritual der Seelenbindung mit Seuchenerfinder Marileth ab.", progress = "Wie immer bin ich so stolz auf Euch, mein Lehrling!", completion = "Von unserem geteilten Wissen wird ganz Maldraxxus profitieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[59598] = { id = 59598, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gut für die Seele", description = "Zwei Seelen sind besser als eine! Wir können bei Weitem mehr gemeinsam als allein erreichen.\n\nAllerdings sind es nicht nur wir beide, die sich allen Gefahren stellen. Es gibt viele mehr, die uns in den kommenden Schlachten beistehen.\n\nSprechen wir mit Merick, um mehr darüber zu erfahren. Seid nicht schüchtern, ich kann Euch vorstellen!", sourceObjective = "Sprecht mit Merick.", sourceObjectiveStatus = "unverified-source-field" }
quests[59599] = { id = 59599, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bewahrung des Hofes" }
quests[59600] = { id = 59600, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fauldornärger" }
quests[59601] = { id = 59601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf die Vorhallen" }
quests[59603] = { id = 59603, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Dienste der Schattenlande", description = "Als Maldraxxi sind wir für die Sicherheit der Schattenlande verantwortlich.\n\nWenn sich Feinde offenbaren, treten wir ihnen entgegen!\n\nDie Schattenlande stehen vielen Bedrohungen gegenüber, weit mehr, als je einer von uns allein bewältigen könnte. Und genau da komme ich ins Spiel.\n\nIch bin so etwas wie Euer Auge dort draußen. Lasst es mich anhand einer einfachen Aufgabe für Marileth demonstrieren, auf dass Ihr beide die Früchte meiner Arbeit ernten könnt.", sourceObjective = "Verwendet den Befehlstisch, um Marileth auf ein Abenteuer zu entsenden.", completion = "Und so ist es, als hättet Ihr persönlich den Kampf angeführt! Hervorragende Arbeit, wenn ich das so sagen darf.", sourceObjectiveStatus = "unverified-source-field" }
quests[59604] = { id = 59604, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Bezwingen der Bestie" }
quests[59605] = { id = 59605, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Bezwingen der Bestie" }
quests[59607] = { id = 59607, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Bezwingen der Bestie", progress = "Fiese Fledermaus kriegt auf die Mütze! Brauche Munition! Munition in Schauerkuppe!", completion = "Haha! Auf die Mütze!" }
quests[59609] = { id = 59609, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Ruhe für die Toten", description = "Ausgezeichnete Arbeit, mein Lehrling! Ihr habt Euer Training abgeschlossen und seid nun ein wahrer Nekrolord.\n\nDas bedeutet auch, dass Ihr zusätzliche Verantwortung übernommen habt. Das ist die Last des Genies!\n\nIch glaube, Baronin Draka wollte mit Euch sprechen.", sourceObjective = "Meldet Euch bei Baronin Draka.", completion = "Ich hoffe, Ihr seid wohlauf. In Maldraxxus gibt es keine Rast für die Erschöpften.", sourceObjectiveStatus = "unverified-source-field" }
quests[59615] = { id = 59615, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein blindes Huhn findet auch mal ein Korn", description = "Als ich hörte, dass Ihr Konstrukte und ein Heim für Seelen baut, die Maldraxxus noch immer treu sind, habe ich mich auf die Suche nach Euch gemacht!\n\nIch bin treu und wollte schon immer einen Konstruktkörper, aber der Markgraf wollte keinen bauen, der zu meinen natürlichen Neigungen passt.\n\nIch habe mein ganzes Leben mit diesem Fluch zugebracht. Er ist alles, was ich ich kenne, und alles, was ich noch immer will.\n\nWürdet Ihr ein Konstrukt für mich bauen?", sourceObjective = "Nehmt die Spezifikationen für Neenas Konstrukt auf.", completion = "Ich kenne diese Seele, sie ist stark und sehr loyal. Sie würde uns sehr helfen, so ein außergewöhnliches Konstrukt zu bauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[59616] = { id = 59616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einmannarmee", description = "Mevix wird den Angriff anführen, aber Ihr werdet ihn zu Ende bringen. Es gibt keine Verstärkung, keine Kavallerie.\n\nNur Euch und Eure Runenklinge.\n\nZeigt mir Eure Macht. Belagert das Haus der Konstrukte und bringt es zum Einsturz!", sourceObjective = "Trefft Secutor Mevix nahe des Hauses der Konstrukte.", completion = "Eure Stimme... Ihr seid kein Maldraxxi?", sourceObjectiveStatus = "unverified-source-field" }
quests[59617] = { id = 59617, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steinscheusalsaboteure" }
quests[59621] = { id = 59621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eiersalat", description = "Wie Ihr seht, haben wir ein Gormproblem.\n\nIch weiß nicht, was mit ihnen los ist. Sie sind in letzter Zeit größer und feindseliger geworden, vermutlich wegen der Animadürre. Wenn niemand sie aufhält, werden sie noch alles fressen!\n\nIhre Eierproduktion ist außer Kontrolle. Wir können nicht zulassen, dass ihre Population noch größer wird. Bitte geht in ihre Nester und vernichtet so viele Eier, wie Ihr finden könnt.", sourceObjective = "Vernichtet 10 Gormeier an den Ufern des Lebens.", completion = "Das sollte ihre Zahl hoffentlich verringern. Ich danke Euch für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[59622] = { id = 59622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pfleger pflegen", description = "Die Eier sind ein Problem, aber das sind die Gorm, die sich um sie kümmern, auch.\n\nDie Eipfleger sind in Abwesenheit einer Matriarchin die Anführer des Schwarms. Wenn sie nicht kontrolliert werden, produzieren sie immer mehr Eier und wir stehen gleich wieder am Anfang. Schlimmer noch, einer könnte sich auch in eine Königin verwandeln.\n\nSie sind einfach zu groß und feindselig, als dass wir sie unter Kontrolle halten könnten. Ich sehe keine andere Lösung, als sie zu erledigen.", sourceObjective = "Tötet die Eipfleger Tiom, Blome und Erys.", completion = "Irgendwann wird die Population weitere Pfleger hervorbringen. Ihr habt uns aber wertvolle Zeit verschafft.", sourceObjectiveStatus = "unverified-source-field" }
quests[59623] = { id = 59623, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Viel Gemurre ums Gesurre", description = "Was sagt Ihr? Ihr habt Lust auf eine weitere Jagd?\n\nEiner dieser kleinen fliegenden Plagegeister ist zu einem sehr großen fliegenden Plagegeist geworfen. Große, makellose Gormteile sind auch in guten Zeiten schwer zu finden und ein Schmied weiß eine Herausforderung immer zu schätzen.\n\n<Cavina spricht leiser und beugt sich zu Euch.> Außerdem mache ich mir Sorgen um die Sicherheit meiner Familie und aller anderen im Hain.\n\nBringt mir den Stachel von dem Dickerchen und es soll Euer Schaden nicht sein.\n\nAbgemacht?", sourceObjective = "Bringt Todessurrers Stachel zu Gormschmied Cavina.", progress = "Ich muss sagen, ich freue mich auf die Gelegenheit, mit so einem feinen Exemplar zu arbeiten.", completion = "Ja, das nenne ich mal einen guten Gorm. Ich mache Euch etwas Besonderes daraus.", sourceObjectiveStatus = "unverified-source-field" }
quests[59625] = { id = 59625, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das einzige Mittel", sourceObjective = "Trefft Euch mit dem Paragon des Mutes in der Bastion.", completion = "Eure Ankunft wird erwartet. Wir wollen Resultate.", sourceObjectiveStatus = "unverified-source-field" }
quests[59641] = { id = 59641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nation Kul Tiras", description = "Kul Tiras besitzt die größte Seestreitmacht von Azeroth und ist ein einstiges Mitglied der Allianz. Aber leider haben wir kaum noch Kontakt zu ihnen, seit Jainas Vater, Lordadmiral Daelin Prachtmeer, in Theramore getötet wurde.\n\nViele waren der Meinung, dass Jaina so überzeugt von der Aussicht auf einen Frieden zwischen Allianz und Horde gewesen sei, dass sie an diesem Tag ihren eigenen Vater verraten hat. Vielleicht spürt sie jetzt, dass die Zeit gekommen ist, die Vergangenheit ruhen zu lassen.\n\nSo sehr ich die Vorstellung hasse, Jaina einem Risiko auszusetzen... Kul Tiras muss sich wieder der Allianz anschließen.\n\nMöge das Licht mit Euch sein.", sourceObjective = "Sprecht mit Lady Jaina Prachtmeer im Hafen von Sturmwind.", completion = "Nach all der Zeit wieder zu Hause.", sourceObjectiveStatus = "unverified-source-field" }
quests[59642] = { id = 59642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haareraufen", description = "Die Monstrositäten sind gut organisiert und ausgestattet. Wir konnten noch nichts an Boden gewinnen.\n\nEtwas Chaos in ihrer Versorgung und der Verstärkung könnte uns einen Vorteil verschaffen.\n\nIhr müsst Euch hinter den feindlichen Linien durchkämpfen und drei Monstrositäten ausschalten, die sich um die Versorgung kümmern.", sourceObjective = "Tötet Stratege Orco, Lubber Jalrax und Munitionist Vizic.", sourceObjectiveStatus = "unverified-source-field" }
quests[59643] = { id = 59643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renntag in den Bollwerken!" }
quests[59644] = { id = 59644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vom Licht geblendet", sourceObjective = "Benutzt die Spiegel über Sündensturz, um die Tore von Schloss Nathria zu versiegeln.", progress = "Hoffentlich seid Ihr da draußen nicht zu sehr verbrannt.", completion = "Das sollte uns Zeit verschaffen und uns eine Schneise schlagen. Nun dazu, wie wir die Situation zu unserem Vorteil nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[59645] = { id = 59645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tod regnet herab", sourceObjective = "Tötet 30 gegnerische Streitkräfte.", progress = "Lasst Gerechtigkeit walten.", completion = "Unser Wille ist geschehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[59648] = { id = 59648, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stückweiser Frieden", description = "Diese maldraxxischen Teufel haben meinen Tempel erneut besetzt. Sie haben sich bei dieser Rückkehr hinter Schilden voller Nekromantie verschanzt.\n\nMeine Jünger, diejenigen, die nicht von Euren niederträchtigen Kameraden gefangen genommen und hingerichtet wurden, melden den Kern eines nekrotischen Bollwerks im Süden. Wir können es nicht mit ihren Streitkräften aufnehmen, bis der Schild zerstört ist.\n\nSorgt für dessen Beseitigung. Ich werde Eure Anwesenheit sonst nicht dulden.", sourceObjective = "Deaktiviert das nekrotische Bollwerk im Süden.", completion = "Wir haben gerade erst begonnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[59650] = { id = 59650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Zögern, keine Kapitulation", description = "Ich kann nicht ergründen, wo diese Konstrukte ihre Verstärkung hergeholt haben, doch sind wir erneut in der Unterzahl. Der Gedanke an meine gefallenen Jünger erzürnt mich zutiefst.\n\nIhr werdet das wiedergutmachen.\n\nDie Abtrünnigen haben im nördlichen Bereich des Tempels eine Stellung errichtet. Ihre nekrotische Magie hat ihnen einen Schild verliehen, der sie vor Distanzangriffen schützt. Macht ihn unbrauchbar.\n\nLasst Euch nicht aufhalten. Das ist der Weg des Mutes.", sourceObjective = "Macht das nördliche Bollwerk unbrauchbar.", completion = "Das ist der Anfang, die Dinge wieder ins Lot zu bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[59653] = { id = 59653, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unbezwingbarer Mut", description = "Wir haben dafür gesorgt, dass die feindlichen Verstecke schutzlos sind. Meine Jünger werden Vorbereitungen treffen, um unser Land von der Verderbnis zu säubern, die Euresgleichen über unsere Heimat gebracht haben.\n\nDoch es sind noch mehr im Inneren Sanktum des Tempels. Ihre Verteidigung verhindert geballte Luftangriffe, aber ich kann eine Stellung sichern. Wir werden die Bresche überwinden und sie vernichten.", sourceObjective = "Durchquert die Bresche mit Xandria.", completion = "Weiter kann ich Euch nicht bringen. Nutzt die Chance!", sourceObjectiveStatus = "unverified-source-field" }
quests[59656] = { id = 59656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reden wie ein Wasserfall", description = "<Thorodir atmet erleichtert tief durch.>\n\nIch würde sagen, das war es. Die Ufer sind jetzt dank Euch überwiegend sicher. Den Rest der Säuberung können wir ab jetzt selbst bewältigen.\n\nDie Lady von den Wasserfällen wird an Eurem Erfolg hier interessiert sein. Warum geht Ihr nicht zu ihr und überbringt Ihr die guten Neuigkeiten?", sourceObjective = "Meldet Euch bei der Lady von den Wasserfällen im Schimmerkaskadenbecken.", completion = "Ah, das sind wunderbare Neuigkeiten. Ich danke Euch für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[59658] = { id = 59658, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dominanz beweisen" }
quests[59659] = { id = 59659, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Absolution aus der Luft", description = "Meine Kyrianer hätten schon längst versucht, zurückzuschlagen, aber diese abscheulichen Eindringlinge sind sehr hinterhältig.\n\nIhre Nekromanten verpesten die Luft mit ihrer widerwärtigen Macht, die unsere Schwingen zersetzt.\n\nIch kann keinen Angriff führen, bis sie ausgelöscht sind. Kümmert Euch um diese Besudler und ich lasse die anderen büßen.", sourceObjective = "Tötet die drei Besudler.", completion = "Jetzt sind wir bereit.", sourceObjectiveStatus = "unverified-source-field" }
quests[59660] = { id = 59660, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein neuer Hof", sourceObjective = "Rekrutiert das Personal, das für die Eröffnung des Gluthofs nötig ist.", completion = "Dieser Hof wird sich nicht von allein halten. An die Arbeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[59661] = { id = 59661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Probe für den Gluthof", sourceObjective = "Helft Temel, die Probe für den Gluthof abzuhalten.", completion = "Alles in allem lief das doch überraschend gut. Wir beide haben wirklich ein Händchen für die Planung von Feiern.\n\nWir sind bereit, unseren ersten echten Gluthof vorzubereiten!", sourceObjectiveStatus = "unverified-source-field" }
quests[59674] = { id = 59674, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freundschaftliche Rivalität", description = "Ah, eine frische Seele! Euer Blickwinkel könnte sich für uns als nützlich erweisen.\n\nNemea und ich haben unterschiedliche Ansichten. Sie preist ihre Larions, einheimische Kreaturen aus der Bastion, die sie aufzieht und als ihre Begleiter ausbildet.\n\nIch dagegen bin der Meinung, dass Phalynx die überlegeneren Wesen sind. Sie sind effizient, gehorsam und umgänglich.\n\nBitte, kommt und lernt beide Wege kennen. Vielleicht könnt Ihr entscheiden, welche Lebensweise besser ist.", sourceObjective = "Trefft Pelodis am Schmiedefeueraußenposten oder Nemea in Nemeas Zuflucht.", completion = "Ich fühle mich geehrt, dass Ihr zuerst zu mir gekommen seid. Erlaubt mir, Euch meine Gepflogenheiten zu zeigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[59676] = { id = 59676, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ernter der Begierde", description = "Also, das läuft so: Wir schlammen Euch jetzt richtig ein, damit Ihr wie einer der Diener daherkommt. Das Zeug ist gegen Diebstahl geschützt, wenn die Kleidung also denkt, dass sie geklaut wird, teleportiert sie wieder hierher... mit Euch drin.\n\nIhr SOLLTET die Gräfin mit Eurer Botschaft erreichen können. Einfach lächeln, nicken, mit niemandem reden und niemandem und nichts in die Augen sehen, das Flügel hat. Die werden nämlich wissen, dass Ihr da nicht hingehört.", sourceObjective = "Schmuggelt Euch auf die Ewige Terrasse und bringt Prinz Renathals Botschaft zur Gräfin.", completion = "Ah, die Gräfin. Herrin des Hofs. Man sollte immer davon ausgehen, dass sie nie allein und zu großer Heimtücke fähig ist.\n\nHmm... Heimtücke...", sourceObjectiveStatus = "unverified-source-field" }
quests[59678] = { id = 59678, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Selbstversorgung abgeschnitten", description = "Diese Überläufer waren fleißig. Sie haben weitere Portale in der Gegend geöffnet, damit sie problemlos ihre Reihen auffüllen können.\n\nAuch das Paragon mit seiner Macht kann keine endlose Armee auslöschen. Lasst uns die Portale zerstören. Ohne Verstärkung, um ihre Truppenstärke zu halten, werden sie sicherlich scheitern.", sourceObjective = "Deaktiviert 6 nekrotische Portale.", progress = "Die Zeit für Gnade ist vorbei.", completion = "Sie können sich nicht länger selbst versorgen. Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[59680] = { id = 59680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vesiphones vermaledeite Vesperglocke" }
quests[59698] = { id = 59698, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht reinen Tisch", description = "Endlich gehören uns die Himmel wieder... Und an diesen Himmeln zieht der Sturm unserer Rache auf.\n\nKommt, Ihr, die Ihr Euch als wahre Maldraxxi bezeichnet. Ihr möchtet das Unrecht derer ungeschehen machen, die Ihr einst Verbündete nanntet?\n\nLasst Gerechtigkeit auf sie herabregnen! Zeigt kein Erbarmen!", sourceObjective = "Fliegt mit Xandria und tötet Maldraxxi.", completion = "Für Mut!", sourceObjectiveStatus = "unverified-source-field" }
quests[59700] = { id = 59700, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die letzte Anstrengung", description = "Das Böse, das die Bastion bedroht, zerfällt unter uns. Aber wenn wir zulassen, dass diese grausame Baronin sich ihrer gerechten Strafe entzieht, haben wir den Kampf nicht gewonnen.\n\nSie kauert in der Nekropole dort oben und wirft ihren Schatten auf diesen einst heiligen Tempel.\n\nWir werden diesen Dolch aus unserem Rücken ziehen. Die Wunde wird heilen.", sourceObjective = "Tötet Baronin Antolyte.", completion = "Möge die Erinnerung an sie an diesem Ort verblassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[59701] = { id = 59701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neutraler Boden", description = "Jetzt, da wir eine Hochburg als Operationsbasis haben, müssen wir mit der nächsten Phase meines Plans beginnen, dem Meister die Kontrolle über Revendreth zu entreißen.\n\nWir müssen den Hof der Ernter dazu bewegen, zusammenzukommen. Allerdings nicht hier, das wäre glatter Selbstmord.\n\nGeht zu meiner alten Hochburg, dem Finsterwallturm, und stellt diese Banner an den vier markantesten Punkten des Turms auf. Dann werden die Kräfte der Ernter und des Meisters das neutrale Treffen nicht stören können.", sourceObjective = "Platziert vier Renathalbanner am Finsterwallturm.", completion = "Sie sehen vielleicht wie einfache Banner aus, aber mit den richtigen Worten und passenden Zaubern werden sie diesen Ort in ein zeitweiliges Refugium verwandeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[59703] = { id = 59703, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bomberangriff" }
quests[59705] = { id = 59705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht vergessen" }
quests[59706] = { id = 59706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einladung für die Gräfin", description = "Die Gräfin, Ernterin der Begierde.\n\nIhr Verstand ist schärfer als die meisten Schwerter. Auch wenn ich sie niemals eine Waffe habe tragen sehen, kann man davon ausgehen, dass sie nie ohne Schutz ist.\n\nIhr Anwesen ist ein Spiegelbild des meinigen auf der nordöstlichen Seite von Schloss Nathria. Der Schlossdistrikt unterstand ihrer Herrschaft und ihre Autorität hält die Adeligen in Schach.\n\nSie wird sich sicher über eine geheime Nachricht freuen. Ich werde einen Gräber mit einem Plan zur Unterwanderung ihrer Gruppe vorausschicken. Trefft ihn auf der Brücke der Versuchungen. Viel Glück.", sourceObjective = "Trefft Knüppelfratze auf der Brücke der Versuchungen, die zur Ewigen Terrasse führt.", completion = "Gut, dass Ihr vor den Patrouillen hier seid. Ich hab hier keine Parkerlaubnis.", sourceObjectiveStatus = "unverified-source-field" }
quests[59707] = { id = 59707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einladung für den Zehntherrn", description = "Der Zehntherr ist fies und feige, genau wie jeder andere Ernter des Neids vor ihm.\n\nTrotzdem ist seine Macht größer, als wir momentan einschätzen können. Ich habe Nadjia und Temel nach Stolzsturzweiler im Süden gesandt, um einen Weg zu finden, auf dem man den Zehntherr sicher und vor allem lebendig erreichen kann.\n\nTrefft sie dort und seid vorsichtig. Der Zehntherr tötet Euch im Handumdrehen, wenn er sich davon mehr Macht oder Autorität verspricht.", sourceObjective = "Sprecht mit Nadjia Nebelklinge in Stolzsturzweiler.", completion = "Bereit, mit Anmut unterzugehen?", sourceObjectiveStatus = "unverified-source-field" }
quests[59708] = { id = 59708, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einladung für die Steinhauerin", description = "Das Zornamulett befindet sich in den Händen der Steinhauerin. Sie ist uralt, mächtig und hat einst die Steinlegion erschaffen.\n\nBei ihr kommen wir mit subtilen Mitteln nicht weit. Ich weiß, dass es gefährlich ist, aber würdet Ihr Euch mit General Draven am Tor der Dominanz treffen?\n\nWenn die Steinhauerin teilnehmen soll, muss sie erfahren, wie wichtig unser Anliegen ist, und das bedeutet, dass Ihr und Draven direkt durch die Vordertür reinmarschieren müsst.", sourceObjective = "Sprecht mit General Draven am Tor der Dominanz.", completion = "Das wird kein leichter Tag.", sourceObjectiveStatus = "unverified-source-field" }
quests[59709] = { id = 59709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Leben nach dem Tode geht weiter", description = "Ein neuer Morgen dämmert für die Bastion. Ich hatte meine Bedenken, aber Ihr habt bewiesen, dass es in Maldraxxus noch Ehre gibt.\n\nNehmt meine Hand noch einmal. Ich bringe Euch zum Tempeleingang zurück.\n\nLasst alle Maldraxxi von Eurem Sieg erfahren. Stellt um des Friedens Willen sicher, dass dies nie wieder geschieht.", sourceObjective = "Fliegt mit Xandria zum Eingang des Tempels des Mutes.", completion = "Mögen sich unsere Wege wieder kreuzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[59710] = { id = 59710, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine merkwürdige Einladung", description = "Psst. Ihr da. Ja, Ihr.\n\nSeid Ihr <der Schlundgänger, über den/die Schlundgängerin> über die; alle schnattern? Hm. Ich dachte, Ihr wärt größer.\n\nJedenfalls möchte der Zuchtmeister gerne, ähhhm... \"seine Anerkennung ausdrücken und eine Einladung für einen Besuch seines Wirkungsbereichs aussprechen\". Das ist ein hochtrabender Ausdruck für einen Haufen Steine, die ich und meine Kumpels ausgraben.\n\nWenn Ihr also Lust habt und so, dann macht Euch auf zum Fresserdickicht und trefft Euch mit dem Kurier des Blutsaugers, Araak. Er wird Euch alles erklären.", sourceObjective = "Trefft Euch mit Kurier Araak.", progress = "Der Zuchtmeister wartet nicht gerne.", completion = "Nun, wie es aussieht, ist der Meister gerade fortgegangen. Na toll.", sourceObjectiveStatus = "unverified-source-field" }
quests[59711] = { id = 59711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ernter des Neids", description = "Danke, dass Ihr uns in minimalem Sicherheitsabstand zum Anwesen des Verwalters trefft. Hier gibt es sicher noch genug Leute, die mich gerne in einem Käfig sehen und dafür ein gewisses Risiko in Kauf nehmen würden.\n\nFür Euch und mich ist es zu gefährlich, direkt mit dem Zehntherrn zu sprechen. Er ist einfach zu impulsiv und versucht immer, Denathrius zu gefallen. Wir sollten Temel schicken.\n\nDas Steinscheusal ist ein gewöhnlicher Bote in Revendreth und außer ein paar Beobachtern wird kaum einer seine Ankunft bemerken. Schubst ihn einfach an, wenn Ihr bereit seid.", sourceObjective = "Führt Temel durch das Anwesen des Verwalters und überbringt Prinz Renathals Nachricht dem Zehntherrn.", completion = "Der Zehntherr. Ich glaube, er ist der zweihundertfünfundsiebzigste Verwalter, der über den Dorfdistrikt herrscht.\n\nEr ist auf ebenso gefährliche Weise ehrgeizig wie jeder andere Ernter des Neids vor ihm. Und er wird nur helfen, wenn er glaubt, dadurch mehr Macht zu erlangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[59712] = { id = 59712, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Eigenheiten des Landes", description = "Also, ja, ich weiß nicht, was er von Euch will. Ich arbeite schon ziemlich lange mit ihm zusammen, also schätze ich, dass er Euch für etwas Zwielichtiges in seinem Interesse einsetzen möchte. Aber ich bin da etwas voreingenommen. Ich könnte Euch so viele Geschichten erzählen.\n\nLasst uns nach meiner Freundin Nadjia sehen.", sourceObjective = "Sprecht mit Nadjia und untersucht das Lager von Zuchtmeister Matyas.", progress = "Habt Ihr schon das Tagebuch von Zuchtmeister Matyas gefunden?", completion = "Ich weiß Eure Hilfe zu schätzen, mein Freund. Macht nur weiter so, dann stehe ich in Eurer Schuld.", sourceObjectiveStatus = "unverified-source-field" }
quests[59713] = { id = 59713, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aktive Zutaten", description = "Es wird schwierig sein, mit Matyas fertigzuwerden, bis wir ihm meinen Sündenstein abnehmen können. Wir brauchen etwas, das ihn außer Gefecht setzt.\n\nHolt Ihr mir ein paar Zutaten, <Sterblicher/Sterbliche>? Ich habe einen raffinierten Plan.", sourceObjective = "Sammelt Zutaten für Nadjias Mischung.", progress = "Habt Ihr die Zutaten?", completion = "Das sollte genug sein, um ihn so lange auszuschalten, bis ich meinen Sündenstein habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[59714] = { id = 59714, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein edler Jahrgang", description = "Wir brauchen etwas Besonderes als Grundlage für unsere Mischung. Um ihn dazu zu bringen, sie zu trinken, muss er glauben, dass Ihr ihm ein Geschenk gebracht habt.\n\nEr hält sich nämlich für einen echten Kenner. Irgendein alter, verstaubter Jahrgang wird ihn in Versuchung führen.\n\nSeht doch mal im alten Keller nahe den Ruinen nach. Dort wurden früher die Vorräte verwahrt. Vielleicht findet sich noch eine Flasche da unten. Araak und ich arbeiten derweil die weiteren Details aus.", sourceObjective = "Holt eine edle Flasche für Nadjia.", progress = "Habt Ihr ein geeignetes Getränk gefunden?", completion = "Ah, die ist perfekt. Er wird dieser Versuchung nicht widerstehen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[59715] = { id = 59715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachricht für Matyas", description = "So, es ist alles vorbereitet. Wenn Ihr soweit seid, bittet Kurier Araak darum, Zuchtmeister Matyas herbeizurufen, als wäret Ihr gerade eingetroffen.\n\nIch bin mir sicher, dass das Geschenk seines Lieblingsgetränks ihn in Versuchung führen wird, und dass das von uns angemischte Gift ihn lange genug außer Gefecht setzen wird, um ihm meinen Sündenstein abzunehmen.\n\nUnser Plan wird reibungslos funktionieren!", sourceObjective = "Ruft Zuchtmeister Matyas zurück ins Lager.", completion = "Ah, der Schlundgänger! Ich habe viel von Euch gehört.", sourceObjectiveStatus = "unverified-source-field" }
quests[59716] = { id = 59716, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Berauscht und beraubt", description = "<Ein Sterblicher/Eine Sterbliche> in Revendreth. Man sagt, Ihr könnt den Schlund durchqueren? Das ist erstaunlich. Ich habe so viele Fragen an Euch.\n\nAber meine Neugier muss zunächst zurückstecken. Ich habe ein... nennen wir es... Angebot für Euch, das uns beiden zum Vorteil gereichen könnte. Wenn Ihr wirklich frei durch diese Lande reisen könnt, dann habt Ihr im Gegensatz zu mir Zugriff auf bestimmte Informationen.\n\nSeht Ihr jetzt, wie Ihr mir nützen könnt? Kommt, lasst uns diese Sache noch weiter erörtern.", sourceObjective = "Vergiftet den Zuchtmeister, um Nadjias Sündenstein zu erhalten.", progress = "Meinen Sündenstein, bitte.", completion = "Oh, gut gemacht! Einen Augenblick lang, als Ihr das Gift nahmt, hatte ich schon Sorge um Euch. Aber Ihr scheint sehr widerstandsfähig zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[59717] = { id = 59717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht vergessen" }
quests[59718] = { id = 59718, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Segelnder Sonnenschirm" }
quests[59719] = { id = 59719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hof", description = "Nun, wir sind jetzt beschlussfähig. Ihr habt alles für uns getan, was zu diesem Zeitpunkt möglich ist, <Schlundgänger/Schlundgängerin>.\n\nJetzt liegt es an mir, ob ich diese uralten Narren davon überzeugen kann, dem größten Gönner ihrer Realität zu entsagen und sich stattdessen mir anzuschließen, einem gefallenen Rebellen mit einem \"neuen\" Plan.\n\nMal sehen, ob ich sie mitreißen kann. Wünscht mir Glück.", sourceObjective = "Wohnt der Zusammenkunft des Hofs der Ernter bei.", completion = "Nun, das hätte wirklich besser laufen können. Ich hätte nicht gedacht, dass sie alle sofort hier erscheinen, aber ich hatte auf vielleicht einen oder zwei von ihnen gehofft.\n\nJetzt müssen wir es eben auf die harte Tour versuchen. Wir sollten uns zurückziehen, bevor sie Truppen schicken, um den Turm zurückzuerobern.", sourceObjectiveStatus = "unverified-source-field" }
quests[59720] = { id = 59720, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ernterin des Zorns", description = "Wir wandeln in den geflügelten Schatten meiner Waffenbrüder und -schwestern. Ich habe Steingeborene ausgebildet, seit sie erstmals aus dem Stein gemeißelt wurden.\n\nDies ist ein uralter Ritus. Wenn wir es schaffen, diese Brücke zu überqueren und alles zu besiegen, was sich uns in den Weg stellt, bekommen wir vielleicht eine Audienz bei der Mutter der Steingeborenen. Erzürnt sie besser nicht, denn unser Rückweg wird möglicherweise nicht sicher sein.\n\nIch kann mir wirklich Schöneres vorstellen.", sourceObjective = "Überquert die Brücke des Trotzes zu Fuß.", completion = "Ich erinnere mich noch daran, wie die Steinhauerin den ersten Steingeborenen mit Anima Leben eingehaucht hat.\n\nMacht niemals den Fehler, ihr Mitgefühl für ihre Schöpfungen als Schwäche zu interpretieren. Das Zornamulett trägt sie nicht umsonst.", sourceObjectiveStatus = "unverified-source-field" }
quests[59721] = { id = 59721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zur Jagd werden", description = "<Reldorn grinst Euch an.>\n\nEr hat gewusst, dass Ihr zurückkommen werdet! Der Gehörnte Jäger hat sich schon daran gemacht, das Jagdgebiet vorzubereiten. Er hat gesagt, Ihr sollt Euch so bald wie möglich zu ihm gesellen.\n\nJetzt, da Ihr die Materialien für die Falle habt, müsst Ihr nur zu ihm gelangen...\n\nDieses Gebiet zu durchqueren, ist gefährlich. Ich habe jedoch einen Zauber vorbereitet, dank dem Ihr der Aufmerksamkeit der umherstreifenden Kreaturen entgehen könnt. Vielleicht könntet Ihr, wenn er nützlich ist, ein gutes Wort einlegen für...\n\n<Er räuspert sich.> Wie dem auch sei, wir sollten uns auf Eure Beute konzentrieren. Weidmannsheil!", sourceObjective = "Findet Huln Hochberg in der Ältestenwehr.", completion = "Ihr kommt gerade rechtzeitig. Meine Vorbereitungen sind fast abgeschlossen.", sourceObjectiveStatus = "unverified-source-field" }
quests[59722] = { id = 59722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nekropolenklau", description = "Die Nekropole ist sicher, aber wir können nur für kurze Dauer ein Portal zum Sitz des Primus aufrechterhalten.\n\nKhaliiq wird mit Euch zurückkehren und daran arbeiten, eine dauerhafte Portalverbindung einzurichten.", sourceObjective = "Benutzt das Portal, um Khaliiq im Sitz des Primus zu treffen.", completion = "Als ob wir nie fort gewesen wären.", sourceObjectiveStatus = "unverified-source-field" }
quests[59724] = { id = 59724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Feld der Ehre", description = "Dank Euch, {name}, stehe ich zum ersten Mal seit... nun, seit langer, langer Zeit nicht mehr unter Matyas' Kontrolle.\n\nJetzt werden wir meine Rache in die Tat umsetzen.\n\nIch habe Euch mit der feierlichen Pflicht als <mein Sekundant/meine Sekundantin> für dieses Duell betraut. Ich kenne die Etikette in Eurem Heimatland nicht, aber in meinem ist es Eure Aufgabe, das Feld zu sichern. Matyas und seine Anhänger haben in der nahe gelegenen Welkfallruine Lager bezogen. Wenn ich mich nicht täusche, wird er dorthin geflohen sein.\n\nIch werde mich auf den Kampf vorbereiten und mich Euch bald anschließen.", sourceObjective = "Vertreibt Zuchtmeister Matyas' Anhänger aus der Welkfallruine.", completion = "Also, einen stimmigen Schauplatz für den Kampf hat er sich jedenfalls ausgesucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[59725] = { id = 59725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archivar am Abgrund", description = "Wenn der Fluch nicht aufgehoben wird, wird Qadarin dahinsiechen, bis nichts mehr übrig ist!\n\nWir haben Flüche wie diesen früher ständig gebunden und versiegelt, aber wir hatten es schon seit Ewigkeiten nicht mehr mit einem zu tun.\n\nGeht zu Archivar Dreyden im Hain der Erinnerung. Er wird wissen, um welchen Fluch es sich handelt, und kann Euch die entsprechende Schriftrolle geben.\n\nBringt sie her, damit wir herausfinden, was wir brauchen, um einen Gegenfluch zu wirken.\n\nBeeilt Euch, {name}!", sourceObjective = "Sprecht mit Archivar Dreyden im Hain der Erinnerung.", completion = "Bitte sagt mir, dass Ihr hier seid, um mit dem Sprigganproblem zu helfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[59726] = { id = 59726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es ist eine Falle", description = "Endlich, die Stunde meiner Rache!\n\nMatyas wird sicherlich erneut fliehen, wenn er mich als Erste erblickt, also müsst Ihr ihn an meiner statt stellen, <mein Freund/meine Liebe>. Wenn er dann abgelenkt ist, attackiere ich ihn.\n\nAb dann ist Eure Pflicht als <mein Sekundant/meine Sekundantin> eine reine Formalität. Ihr müsst sicherstellen, dass Matyas das Duell ehrt und nicht betrügt. Wenn er genau das tut, und das ist unvermeidlich, erwarte ich, dass Ihr mir helft, ihn zu besiegen.\n\nEr befindet sich direkt hinter dem Fallgatter dort.", sourceObjective = "Nähert Euch Matyas, um das Duell zu beginnen. Unterstützt Nadjia, wenn Matyas betrügt.", progress = "Matyas entschuldigt sich oder er stirbt.", completion = "Ich hätte eine Entschuldigung akzeptiert, aber er hat betrogen und den Preis bezahlt.", sourceObjectiveStatus = "unverified-source-field" }
quests[59731] = { id = 59731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein erwarteter Gast", description = "Während wir auf Nachricht von Huln warten, hat sich eine weitere wichtige Angelegenheit ergeben.\n\nBwonsamdi ist in den Ardenwald zurückgekehrt. Lord Herne glaubt, dass er hier ist, um eine Audienz bei der Winterkönigin zu erbitten.\n\nDer Loa des Todes verfolgt jedoch einen anderen Zweck. Einen, den ich in meinen Träumen erblickt habe.\n\nTrefft Euch mit Bwonsamdi. Entdeckt, was das Schicksal für Euch beide bereithält.", sourceObjective = "Trefft Bwonsamdi im Herz des Waldes im Ardenwald.", completion = "Der alte Bwonsamdi wusste doch, dass Ihr zu mir komm'n werdet. Ich hab' was, das Ihr hör'n solltet...", sourceObjectiveStatus = "unverified-source-field" }
quests[59732] = { id = 59732, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etwas Besonderes für die Winterkönigin", description = "Wie Ihr mit Mueh'zala umgesprung'n seid, war toll. Ich will mich erkenntlich zeig'n. Wir sin' doch schließlich Freunde... ooooder?\n\nDer fiese Loa is' mir jetzt ausgeliefert. Er hat was von Dingen gemurmelt, die er der Winterkönigin geklaut hat.\n\nKommt mit zu meiner Nekropole. Dann könnt Ihr seh'n, wovon der alte Bwonsamdi redet.\n\nIhr kommt mit was ganz Tollem für ihre Majestät zurück... gaaanz toll.", sourceObjective = "Reist mit Bwonsamdi zur Nekropole in Nazmir.", completion = "Wo Ihr schon da seid, könnt Ihr mir nich' helf'n, den Müll vor der Nekropole wegzuräumen? Um der alten Zeiten willen, hm?\n\nDann könn' wir uns um Mueh'zala kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[59739] = { id = 59739, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Problem beim Inschachhalten eines Todesloas", description = "Ich weiß, Mueh'zala verbirgt immer noch was. Der alte Bwonsamdi wird rausfinden, was das is'.\n\nAber die Anwesenheit von diesem alten Loa holt mir alle Untoten Nazmirs vor die Haustür!\n\nIch brauch Zeit, um Mueh'zala zum Red'n zu bring'n.\n\nDa is'n Troll, Zel'han, der die Untoten anführt. Tötet ihn und zeigt Mueh'zala die Überreste seiner Rüstung.\n\nDas wird seiner Hoffnung, zu entkommen, wohl ein Ende mach'n.", sourceObjective = "Tötet Zel'han den Verräter und nehmt seine Rüstung an Euch.", progress = "Zel'han wird hier mit Euerm Kopf reinmarschier'n. Ich werd Spaß dran haben, wenn Eure Seele im Schlund gequält wird.", completion = "Ich hab Pläne, die sin' älter als Ihr, {race}. Zel'han zu töten, bedeutet mir gar nichts... Versteht Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[59740] = { id = 59740, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reparieren und Wiederherstellen", description = "Ihr habt bereits zahlreiche Spiegel ohne einen Zwischenfall eingestimmt. Ich glaube, es wird Zeit, dass Ihr Euch an der Reparatur versucht.\n\nWenn Ihr erst einmal alle Fragmente gefunden habt, ist es leicht. Aber behaltet dies im Sinn:\n\nReparierte Spiegel sind empfindlich und unberechenbar. Sie zerbersten oft schon nach der ersten Verwendung und bringen Euch keinesfalls verlässlich an einen sicheren Ort.\n\nHier sind für den Anfang ein paar Scherben.\n\nStellt den Spiegel wieder her und schaut, wohin er Euch führt.", sourceObjective = "Repariert den zerbrochenen Spiegel und werdet belohnt.", progress = "Ich habe vollstes Vertrauen in Eure Fähigkeiten.", completion = "Ihr habt einen Segen entdeckt? Gut gemacht! Man weiß nie, was hinter den Spiegeln wartet.", sourceObjectiveStatus = "unverified-source-field" }
quests[59741] = { id = 59741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkles Mojo für einen dunklen Loa", description = "Wie oft muss die Nekropole angegriffen werd'n? Ich nehme an, es hat nie jemand gesagt, es wär' einfach, Bwonsamdi zu verehr'n...\n\nBwonsamdi versucht, Mueh'zala dazu zu zwing'n, seine Geheimnisse zu enthüll'n, un' ich muss meinen Teil dazu beitrag'n, um zu helf'n.\n\nDie Untoten, die in der Nekropole herumwimmeln, werd'n von Mueh'zalas dunklem Mojo animiert.\n\nBwonsamdi braucht was von dem Mojo, um sein Ritual zu beend'n. Bringt die Untoten zur Strecke und besorgt es.", sourceObjective = "Beschafft 100 Einheiten dunkles Mojo von Untoten, die die Nekropole angreifen.", progress = "Habt Ihr mir das Mojo besorgt? Ich brauch es, um Mueh'zala während meines Rituals zu kontrollier'n.", completion = "Seht Euch all das Mojo an! Das is' genau das Richtige, um den kleinen Mueh'zala zum Reden zu bring'n.\n\nMacht Euch keine Sorgen über die andern Untoten da drauß'n. Der alte Bwonsamdi hat 'nen Plan für die.", sourceObjectiveStatus = "unverified-source-field" }
quests[59742] = { id = 59742, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Andre Seite hinausschieben", description = "Viele von Bwonsamdis Anbetern ham es nich' nach drinnen geschafft, als die Untotenschwärme über die Nekropole hergefall'n sin'.\n\nWir brauch'n noch 'n paar von ihnen, um Bwonsamdis Ritual abzuschließ'n, das Mueh'zalas Pläne aufdeckt.\n\nNehmt das Pulver und streut es auf die Anbeter, die draußen festsitz'n. Es sollte alle dunklen Magien vertreib'n, von denen sie befallen sin'.\n\nWas die angeht, die schon tot sin'... Sie werd'n Bwonsamdi aus dem Jenseits dienen. Mehr können wir nich' verlangen.", sourceObjective = "Benutzt seltsames Pulver bei 6 verletzten Anbetern Bwonsamdis.", completion = "Ah, gut, Ihr habt mir alle lebendig'n Seelen besorgt, die ich brauch.\n\nNur keine Sorge weg'n der Verstorbenen. Der alte Bwonsamdi sorgt dafür, dass sie vorm Schlund sicher sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[59743] = { id = 59743, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Spinne an der Mauer" }
quests[59747] = { id = 59747, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine verlorene Seele", description = "Als Gharmal unsere Seelen hier eingesperrt hat, haben viele von uns versucht, sich zu befreien. Doch niemand hat so hart gekämpft wie Bacilia.\n\nSie war ein großer Champion, aber die Gefangenschaft hat ihr den Verstand geraubt, und ihre Seele stürzte in die Dunkelheit. Wir versuchten Äonen lang, ihr Vernunft einzureden, aber sie wird nicht mehr zurückkehren.\n\nBitte beendet ihre Qualen.", sourceObjective = "Bacilia die Verlorene getötet.", completion = "Ich spüre, dass ihr Leiden vorbei ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[59748] = { id = 59748, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Frieden im Tod", description = "{name}, ich möchte Euch um einen Gefallen bitten.\n\nDieses Reich... Das Verständnis von Ehre und Vorsehung, das seine Bewohner leitet, ruft nach mir. \n\nMein Leben folgte solchen Werten. Maldraxxus tat dies einst ebenfalls... Aber ich kehrte aus dem Schlund in ein Land voller Verrat zurück.\n\nIch möchte mit dem Paragon über die Bastion sprechen.", sourceObjective = "Sprecht mit Alexandros mit dem Paragon des Mutes.", completion = "Kommt. Ich habe Euch viel zu zeigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[59749] = { id = 59749, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein leises Flüstern", description = "Das läuft so, {name}. Um Mueh'zala zum Reden zu bring'n, müss'n wir ihm 'n klitzekleines bisschen Lebensessenz von allen hier drin geb'n.\n\nWas guckt Ihr mich so an? Wann hat der alte Bwonsamdi Euch je enttäuscht?\n\nIch werd das Mojo verwend'n, das Ihr besorgt habt, um die Wahrheit aus ihm rauszuhol'n, während er sich nährt.\n\nOh, äh, zwei Sachen noch. Erst mal müsst Ihr 'nen besonderen... Freund herbeiläut'n.\n\nUnd dann geb ich Euch noch mehr von meinem Mojopulver. Benutzt es beim Ritual, wenn meine Anbeter zu schwach werd'n.", sourceObjective = "Schlagt den Gong, um den besonderen Gast herbeizurufen, und benutzt dann das Mojopulver beim Ritual, um Mueh'zala mit Energie zu versorgen.", progress = "Würd' mich echt ma' interessier'n, was der alte Mueh'zala zu sag'n hat...", completion = "Es wird nur einen Loa des Todes geb'n, {name}. Un' das is' der alte Bwonsamdi.\n\nVergesst das besser nich'.", sourceObjectiveStatus = "unverified-source-field" }
quests[59750] = { id = 59750, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit dem Kopf durch die Wand", description = "Ein eifriger Jungspund, der Champion der Arena werden möchte? Die Leute lieben so eine Geschichte, aber Ihr müsst sie erst auf Euch aufmerksam machen. \n\nHier ist der Plan. Marcel Mullby braucht Bluthauerschädel, aber die kann nur ein richtiger Kämpfer besorgen!\n\nTötet ein paar Bluthauer, trennt ihre Köpfe mit meinem Messer ab und liefert sie bei Mullby ab. So bekommt Ihr Anerkennung.", sourceObjective = "Sammelt 12 Bluthauerschädel und liefert sie bei Marcel Mullby ab.", progress = "Ihr habt die Schädel abgeliefert?", completion = "Gute Arbeit, Ihr bekommt Anerkennung. Ich höre die Leute darüber reden, wie Ihr all diese Bluthauer getötet habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[59751] = { id = 59751, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durch den zerrissenen Himmel", description = "Als Sylvanas den Helm der Herrschaft zerschmetterte, wurde sie von der Macht berührt, die daraus freigesetzt wurde.\n\nIch spüre den Widerhall dieser Macht und ich weiß, wo Sylvanas jetzt ist.\n\nWenn Ihr Eure Anführer retten wollt, kann Euch der zerschmetterte Helm einen Pfad öffnen. Aber er kann Euch nicht zurückholen... diesen Weg müsst Ihr allein finden.\n\nDas Risiko ist groß, {name}, aber es gibt keine andere Möglichkeit. Wir werden sofort mit dem Ritual beginnen.", sourceObjective = "Schließt das Ritual am Frostthron ab, um einen Riss in den Schlund zu öffnen.", completion = "Nicht gerade die beste Ankunft, aber immerhin sind wir unversehrt.\n\nIch habe noch keine Spur von Tyrande gefunden. Entweder ist sie woanders gelandet oder ohne uns weitergezogen. Wir sollten die Augen aufhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[59752] = { id = 59752, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine zersplitterte Klinge", description = "Die chaotischen Energien an diesem Ort haben die Ritter der Schwarzen Klinge zerstreut.\n\nIch glaube nicht, dass Azeroths Segen Euch hier erreichen wird, {class}. Wir werden Verbündete brauchen, wenn wir hier überleben wollen.\n\nWir müssen sie schleunigst finden, bevor sie überrannt werden.", sourceObjective = "Sammelt 10 Ritter der Schwarzen Klinge im Tiegel der Verdammten.", progress = "Wir haben keine Zeit für Geschwätz. Suchen wir diese Ritter!", completion = "Wir sind erst wenige Augenblicke hier und unsere Truppen sind bereits stark geschwächt. Aber es wird reichen müssen.\n\nNehmt dieses Horn. Damit könnt Ihr die verbleibenden Streitkräfte der Schwarzen Klinge gegen unsere Feinde sammeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[59753] = { id = 59753, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ende eines Verheerers", description = "Einer der... größeren Unholde... hält einige unserer Ritter in Schach...\n\nEilt ihnen zu Hilfe... bevor wir noch mehr der Unseren verlieren.\n\nGeht... für mich ist es zu spät...", sourceObjective = "Besiegt Verheerer Maroth im Tiegel der Verdammten.", progress = "Unsere Verbündeten fallen, während Ihr untätig herumsteht.", completion = "Ich lasse unsere Ritter nur äußerst ungern zurück, aber gegen diesen Feind haben wir keine Chance.\n\nWir müssen dafür sorgen, dass ihr Opfer nicht umsonst war.", sourceObjectiveStatus = "unverified-source-field" }
quests[59754] = { id = 59754, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf geschwärzten Schwingen", description = "Was für eine Erleichterung, endlich wieder freundliche Gesichter zu sehen. Aber für schöne Worte ist später noch Zeit.\n\nThrall ist verwundet, und die Geschöpfe dieses Reiches machen Jagd auf uns. Wir brauchen sofort einen sicheren Unterschlupf.\n\nKommt, ich glaube, ich kenne genau den richtigen Ort.", sourceObjective = "Helft Jaina, den Schlundgebundenen in Calcis zu entkommen.", progress = "Was macht Ihr denn? Wir haben keine Zeit für Geschwätz!", completion = "Diese Trugbilder werden den Feind eine Weile ablenken, aber so schnell geben sie ihre Jagd nicht auf.\n\nWir müssen uns beeilen!", sourceObjectiveStatus = "unverified-source-field" }
quests[59755] = { id = 59755, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flucht aus der Dunkelheit", description = "Ganz in der Nähe liegt eine Höhle. Wenn wir uns beeilen, können wir uns dort verstecken.\n\nDiese Scheusale werden uns verfolgen, sobald sie uns sehen. Haltet Euch kampfbereit!", sourceObjective = "Eskortiert die versammelten Streitkräfte von Calcis zur Trostlosen Rast.", completion = "Ruht Euch aus, solange Ihr noch könnt, {name}.\n\nIch werde Euch sagen, was ich weiß.", sourceObjectiveStatus = "unverified-source-field" }
quests[59756] = { id = 59756, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine kurze Ruhepause", description = "Anduin war überzeugt, unsere Verbündeten würden uns helfen. Ich gebe zu, ich wollte ihm nicht glauben.\n\nAber Ihr habt bestimmt viele Fragen. Ich helfe Euch gern, so gut ich kann, aber nach...\n\nWie lange ist es jetzt her? Wochen? Länger? An einem so finsteren Ort verliert Zeit jegliche Bedeutung.\n\nVerzeiht mir. Ich weiß nicht viel, aber hört gut zu.", sourceObjective = "Sprecht mit Jaina in der Trostlosen Rast, um zu erfahren, was sie über den Schlund weiß.", progress = "Ich werde Euch sagen, so viel ich kann.", completion = "Nach dieser Schlacht brauche ich Zeit, um mich zu erholen. Thrall braucht ebenfalls etwas Ruhe.\n\nVielleicht könnt Ihr und Mograine nach Antworten suchen, während wir uns ausruhen.", sourceObjectiveStatus = "unverified-source-field" }
quests[59757] = { id = 59757, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feldséance", description = "Wenn diese Seelen über Wissen verfügen, das wir benötigen, müssen wir es uns aneignen.\n\nAuch nachdem die Banshee den Helm zerschmettert hat, kann das Fragment, das Bolvar Euch gab, noch andere beherrschen. Damit solltet Ihr die Geister lange genug kontrollieren können, um ihnen ihr Wissen zu entlocken.\n\nWir müssen sie allerdings ausreichend schwächen, bevor wir sie brechen können. Ich bin sicher, dieser Aufgabe seid Ihr mehr als gewachsen.", sourceObjective = "Erlangt mit dem zerschmetterten Helm der Herrschaft die Kontrolle über 5 Schatten der Boshaftigkeit auf den Ebenen der Qual.", progress = "Wünscht Ihr mit mir zu sprechen oder mit den Toten?", completion = "Zwecklos! Diese Seelen sind viel zu fragmentiert. Von denen bekommen wir gar nichts.\n\nMoment... Was ist das?", sourceObjectiveStatus = "unverified-source-field" }
quests[59758] = { id = 59758, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit den Toten sprechen", description = "Seht, dort am Kamm. Das ist unsere Beute!\n\nUnmöglich zu sagen, wie viele Seelen sich zu diesem Amalgam vermengt haben. Mit etwas Glück kann uns eine von ihnen noch sagen, was wir wissen wollen.", sourceObjective = "Erlangt mit dem zerschmetterten Helm der Herrschaft die Kontrolle über das gepeinigte Amalgam auf den Ebenen der Qual.", progress = "Worauf wartet Ihr noch?", completion = "Findet genug Mäuler, und eins von ihnen wird früher oder später reden.\n\nNehmen wir dieses Ding mit zur Höhle und finden heraus, was es weiß.", sourceObjectiveStatus = "unverified-source-field" }
quests[59759] = { id = 59759, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Löwenkäfig", description = "Anduin wird an einem Ort gefangen gehalten, den die Schemen das Tremaculum nennen. Es ist nicht weit von hier, aber der Weg ist gefährlich.\n\nIch habe mehr als einmal versucht, ihn zu befreien, aber allein vermag ich gegen diese Übermacht nichts auszurichten.\n\nDoch mit Euch wird es uns gelingen.", sourceObjective = "Findet König Anduin Wrynn im Tremaculum.", completion = "Tief in meinen Herzen habe ich gewusst, dass das Licht uns nicht im Stich lassen würde.\n\nUnd Eure Anwesenheit ist der Beweis.", sourceObjectiveStatus = "unverified-source-field" }
quests[59760] = { id = 59760, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schlüssel der Quälerin", description = "Sylvanas glaubt, wir wären gebrochen. Sie glaubt, sie hätte bereits gewonnen.\n\nWir werden ihr zeigen, wie sehr sie sich irrt.\n\nZuerst brauche ich Eure Hilfe. Meine Fesseln sind unglaublich stark. Ohne Schlüssel könnt Ihr mich nicht befreien.\n\nMein... Gefängnis hier steht unter dem Befehl einer Kreatur, die alle die Quälerin nennen. Wahrscheinlich hat sie auch den Schlüssel.", sourceObjective = "Besorgt Euch den Schlüssel der Quälerin von Phael der Quälerin im Tremaculum und öffnet die schlundgeschmiedeten Fesseln.", progress = "Habt Ihr den Schlüssel gefunden?", completion = "Ich hatte schon fast vergessen, wie sich Freiheit anfühlt.\n\nAlso dann, rechnen wir mit diesen Scheusalen ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[59761] = { id = 59761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unverdientes Schicksal", description = "Während meiner Gefangenschaft wurden viele Seelen hierhergebracht. Der Kerkermeister will sie wohl brechen, um sie in seine Knechtschaft zu zwingen... oder Schlimmeres.\n\nKeine Seele verdient solch ein Schicksal, {name}.\n\nDie Schlundgebundenen hier besitzen die Schlüssel für ihre Ketten. Befreit so viele, wie Ihr könnt, dann werden wir sie von hier fortbringen.", sourceObjective = "Sammelt Schlundgebundenenschlüssel von Streitkräften der Schlundgebundenen im Tremaculum und befreit damit 15 gefesselte Seelen.", completion = "Ich wusste, dass ich Euch mit dieser Aufgabe betrauen kann.\n\nAuch im Angesicht einer solchen Übermacht müssen wir stets das Richtige tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[59762] = { id = 59762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Fluss entlang", description = "Unser nächster Schritt liegt auf der Hand. Wir müssen zu Zovaals Kessel. Über diesen furchtbaren Ort habe ich viele fanatische Gerüchte gehört. Es ist eine Art Schmiede, die auf der anderen Seite des Flusses der Seelen liegt.\n\nIch selbst war nur ein paar Mal dort, aber ich habe gesehen, dass einige Soldaten Baine dort gefangen halten. Ist das Glück uns hold, dann ist er vielleicht noch in der Nähe.\n\nSobald er sicher ist, suchen wir den Portalstein, von dem der Schemen gesprochen hat.", sourceObjective = "Überquert die Brücke des Gorgoa, des Flusses der Seelen.", progress = "Wir müssen uns beeilen!", completion = "Der Kerkermeister hat Baine!\n\nEs ist schlimmer, als wir befürchtet hatten...", sourceObjectiveStatus = "unverified-source-field" }
quests[59765] = { id = 59765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr als körperliche Wunden", description = "Auch wenn Baines Körper heilt, eilt sein Geist der Schwelle des Todes entgegen. Ich habe solch finstere Magie schon früher gesehen... beim Schattenmondklan.\n\nDie Schergen des Kerkermeisters müssen Baine mit einem ähnlichen Fluch belegt haben.\n\nDer Fluch der Schattenmonde ließ sich nur durch Zerstörung des Objekts aufheben, das den Geist vergiftet hatte.\n\nDie Zauberer in diesem Reich tragen verzierte Dolche. Das könnte unsere Lösung sein.\n\nWir müssen den finden, mit dem Baine verflucht wurde. Schnell!", sourceObjective = "Besorgt Euch eine Welkklinge von einem schlundgebundenen Seelenzerfetzer in Detrithos.", progress = "Wir können nur hoffen, dass einer der Zauberer hier für Baines Fluch verantwortlich ist.", completion = "Ein Glück, dass wir den Zauberer gefunden haben, der für Baines Fluch verantwortlich war.\n\nIch brauche Eure Hilfe, um seine Verbindung zum Oberhäuptling zu brechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[59766] = { id = 59766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine gute Axt", description = "Es war dumm von mir, meine Axt nach dieser Seehexe zu werfen. Wir müssen einen klaren Kopf bewahren.\n\nDie kommende Schlacht wird nicht einfach. Ich brauche eine andere Waffe für den Kampf um den Portalstein.\n\nSieht aus, als hätten diese Soldaten jede Menge Waffen. Halten wir die Augen nach etwas auf, das ich benutzen kann.", sourceObjective = "Findet unter den Waffen der Schlundgebundenen in Detrithos eine passende Waffe für Thrall.", progress = "Hier muss es irgendwo etwas geben, das ich verwenden kann...", completion = "Nicht so sorgfältig gearbeitet oder so gut ausbalanciert wie die Äxte des Frostwolfklans, aber es wird schon gehen.\n\nAlso los.", sourceObjectiveStatus = "unverified-source-field" }
quests[59767] = { id = 59767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad zur Errettung", description = "Wir müssen uns beeilen, wenn wir den Portalstein erreichen wollen. Die Seele hat gesagt, er steht über dem Kessel. Das heißt dann wohl: irgendwo oben auf dem Kamm auf der anderen Seite.\n\nLeider wimmelt es hier nur so von feindlichen Streitkräften. Wir gehen ihnen lieber aus dem Weg, sonst rufen wir noch den Kerkermeister auf den Plan.\n\nIch kann uns vor neugierigen Blicken verbergen, aber wir müssen alle zusammenbleiben.", sourceObjective = "Führt Eure Verbündeten an Zovaals Kessel vorbei.", progress = "Bleibt dicht bei mir. Wir dürfen es nicht riskieren, von Vasallen des Kerkermeisters entdeckt zu werden.", completion = "Wir haben es geschafft!\n\nWenn wir diesen Portalstein aktivieren, können wir vielleicht endlich von hier verschwinden!", sourceObjectiveStatus = "unverified-source-field" }
quests[59770] = { id = 59770, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steht vereint", description = "<Anduin untersucht den Obelisken aufmerksam.>\n\nIch habe noch nie solche Zeichen gesehen. Ich habe Titanenartefakte erforscht, aber dies scheint aus anderer Hand zu stammen.\n\nHmm. Er reagiert nicht auf mich. Ich glaube, Jaina hat recht. Der Portalstein reagiert auf Eure Anwesenheit.\n\nVielleicht habt Ihr mehr Glück, ihn zu aktivieren.\n\nSeid auf der Hut. Die Streitkräfte des Kerkermeisters haben ihn nicht beachtet, als er inaktiv war, aber man weiß nie, was sie tun, wenn sich das ändert.", sourceObjective = "Aktiviert den erodierten Portalstein in Cocyrus.", completion = "<Der Portalstein scheint auf etwas zu warten.\n\nIhr streckt die Hand aus und berührt seine Oberfläche...>", sourceObjectiveStatus = "unverified-source-field" }
quests[59771] = { id = 59771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschichte der Verderbnis" }
quests[59772] = { id = 59772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forschungszerstörung", description = "Der Kult der Verdammten setzt seine Arbeit in den Hallen von Aldur'thar fort.\n\nInfiltriert ihre Kammern und zerstört ihre Forschung. Das wird sie nicht abhalten, aber es wird uns wertvolle Zeit verschaffen.", sourceObjective = "Zerstört 5 Forschungsnotizen in Aldur'thar.", completion = "Wir werden sehen, wie lange das ihre Bemühungen verzögert.", sourceObjectiveStatus = "unverified-source-field" }
quests[59773] = { id = 59773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach Aufgestiegenen", description = "Wenn Ihr in der Bastion eintrefft, sucht einen der Kyrianer auf. Erklärt ihm, dass Ihr eine Audienz bei der Archon benötigt. Sie ist, genau wie die Richterin, eine der Ewigen, die über die Schattenlande herrschen.\n\nWenn jemand Euch den Weg zur Wahrheit weisen kann, dann die Archon. Vielleicht kennt sie sogar einen Weg, dieser Animadürre ein Ende zu setzen.\n\nSobald Ihr Antworten erhalten habt, dürft Ihr gern nach Oribos zurückkehren.\n\nMöge die Vorsehung Euren Pfad leiten, <Sterblicher/Sterbliche>.", sourceObjective = "Reist zur Bastion und fragt nach den Kyrianern des Schlunds.", completion = "Der Weg steht erneut offen! Gepriesen sei die Archon!", sourceObjectiveStatus = "unverified-source-field" }
quests[59774] = { id = 59774, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen zur Ewigkeit", description = "Verzeiht meine Reaktion. Der Weg aus Oribos war recht lange geschlossen. Wir wussten nicht, ob er jemals wieder geöffnet werden würde.\n\nIch heiße Euch, edle Seele, in der Bastion willkommen. Durch Eure heldenhaften Taten zu Lebzeiten habt Ihr Euch ein glorreiches Schicksal verdient! Ihr sollt <ein Kyrianer/eine Kyrianerin> werden, <ein geflügelter Träger/eine geflügelte Trägerin> der Toten.\n\nIch heiße Kleia. Es wäre mir eine Ehre, Euch unser wunderschönes Reich vorzustellen. Ihr müsst noch vieles lernen, bevor Eure Reise beginnen kann.\n\nSammelt Euch. Wenn Ihr bereit seid, werden wir uns weiter vorwagen.", sourceObjective = "Sprecht mit Kleia.", completion = "Der Begrüßer wird bald all Eure Fragen beantworten. Das ist schließlich sein Zweck.\n\n<Kleia lächelt Euch an.>\n\nIch hoffe, Ihr freut euch. Ich tue das auf jeden Fall!", sourceObjectiveStatus = "unverified-source-field" }
quests[59775] = { id = 59775, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helft Indigo, Penthia zu finden" }
quests[59776] = { id = 59776, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus den Mäulern des Wahnsinns", description = "Ich kann meine Dankbarkeit für Eure Hilfe gar nicht genug zum Ausdruck bringen, Champion.\n\nWir dürfen aber nicht verweilen. Die Kräfte des Kerkermeisters werden bald auf die Unruhen hier aufmerksam werden.\n\nLasst uns diesen Ort sofort verlassen!", sourceObjective = "Kehrt zu Lord Darion Mograine in die Trostlose Rast zurück und hört Euch an, was er erfahren hat.", completion = "Den Helm der Herrschaft einzusetzen, war nicht gerade ein angenehmes Erlebnis. Die darin enthaltene Magie ist... verstörend für die Verstorbenen.\n\nIch bin froh, dass ich ihn Euch zurückgeben kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[59777] = { id = 59777, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helft Calix, Amethia zu finden" }
quests[59778] = { id = 59778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helft Sawn, Varrik zu finden" }
quests[59779] = { id = 59779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helft Moriaz, Knöpfchen zu finden" }
quests[59781] = { id = 59781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Letzte", description = "Ihr seid nicht der erste Neuling, der berühmt werden will. Da gab es viele! \n\nDie letzten paar wollten sich beweisen und einen riesigen Bluthauer töten... Kamen nie zurück! Ihr wollt Anerkennung?\n\nFindet die verschollenen Neulinge und tötet den Bluthauer selbst.", sourceObjective = "Findet 5 Neulingsleichname und tötet Totauge.", completion = "Zu schade um die letzten paar, aber Ihr seid ja noch da!", sourceObjectiveStatus = "unverified-source-field" }
quests[59782] = { id = 59782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ergebene des Todessprechers", description = "Obwohl Todessprecher Kharos vor langer Zeit getötet wurde, setzen die Kultisten in den Bergen in der Nähe seine schändliche Arbeit fort.\n\nDie Rückkehr der Geißel und der Riss im Himmel haben sie offensichtlich ermutigt, unsere Kreuzfahrer zu entführen und scheußliche Alchemieexperimente durchzuführen.\n\nGeht und säubert das Lager von diesen Fanatikern.", sourceObjective = "Tötet 6 dunkle Ritualisten und 6 dunkle Zeloten in Todessprechers Wacht.", completion = "Meine Güte, Ihr habt kurzen Prozess mit ihnen gemacht.\n\nWir werden das Gebiet weiterhin überwachen und der Justiziarin sämtliche Kultistenaktivitäten melden.", sourceObjectiveStatus = "unverified-source-field" }
quests[59783] = { id = 59783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kultistenentführer", description = "Diese verfluchten Kultisten sind unerbittlich!\n\nSie haben uns unvorbereitet erwischt und konnten einige unserer Kreuzfahrer in ihr Lager verschleppen.\n\nDas Licht allein weiß, was sie ihnen dort antun...\n\nMan sagt, Ihr könntet Euch gut behaupten. Unsere Reihen sind jetzt schon gelichtet... Wenn Ihr die Gefangenen retten könnt, stehen wir in Eurer Schuld.\n\nDie Kultisten lauern in ihrem Lager in den Bergen.", sourceObjective = "Beschafft den Schlüssel des Verhörers von Verhörer Grell. Rettet 8 gefangene Aspiranten in Todessprechers Wacht.", progress = "Was könnt Ihr uns Neues berichten?", completion = "Warum überrascht mich das nicht? Bei Euch sieht das schon fast zu einfach aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[59789] = { id = 59789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zehnt und Steuern" }
quests[59800] = { id = 59800, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teamgeist", description = "Selbst wenn wir gegeneinander antreten, sind wir alle Maldraxxi. Das bedeutet, dass wir alle anfeuern, egal auf welcher Seite sie stehen.\n\nBetretet die Arena und übergießt die Herausforderer mit dem Inhalt dieses Fläschchens. Das gibt ihnen vielleicht den Vorteil, den sie brauchen, um den Kampf zu überleben!", sourceObjective = "Übergießt 15 Arenaherausforderer mit dem Fläschchen des Teamgeists.", completion = "Gute Arbeit, Ihr habt die Kämpfer angespornt. Sie werden sich daran erinnern, dass Ihr ihnen geholfen habt... wenn sie überleben.", sourceObjectiveStatus = "unverified-source-field" }
quests[59801] = { id = 59801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nehmt die Macht", description = "Wartet! Bevor Ihr eintretet, möchte ich Euch um etwas bitten.\n\nWir hatten zwar schon lange keinen Wildsamen mehr, aber wir haben noch einen Vorrat an Anima. Er hat uns bei der Abwehr der Gorm gute Dienste geleistet.\n\nWas auch immer in meinem Dorf passiert ist, diese Macht darf nicht in ihren Händen bleiben. Der Ardenwald kann sie in anderen Hainen besser gebrauchen.\n\nSeht Euch im Dorf nach Anima um. Woanders kann sie einem besseren Zweck dienen.", sourceObjective = "Sammelt 8 Animazapfen.", progress = "Konntet Ihr Anima finden?", completion = "Mag sie jetzt dem Wald helfen. Ihre Verluste sollen nicht vergebens sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[59802] = { id = 59802, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das zerfallende Dorf", description = "Dieses Tagebuch gehörte einst Lewor, dem Anführer unseres Hains. Hier steht, dass er etwas gefunden hat, dass beim Kampf gegen die Gorm geholfen hat. Aber was ist, wenn diese Hilfe dieses ganze Chaos erst verursacht hat?\n\nEs gibt nur einen Weg, das herauszufinden. Kommt mit mir ins Dorf, oder das, was davon übrig ist.", sourceObjective = "Folgt Partik.", completion = "N... Nein... das Dorf. Sie sind alle...", sourceObjectiveStatus = "unverified-source-field" }
quests[59803] = { id = 59803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für die Ehre" }
quests[59804] = { id = 59804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tore des Schreckens" }
quests[59805] = { id = 59805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vom Schlund verschlungen", description = "Ihr habt's von Mueh'zala selbst gehört... dank dem alten Bwonsamdi. Es gibt 'nen alten Geist, der im Schlund festsitzt. Ich wette, die Winterkönigin will ihn zurück.\n\nGut, dass Ihr genau da runtergeht, hm? Sollte für Euch 'n Kinderspiel sein.\n\nIch beseitige den Rest der Untoten hier. Trefft den alten Bwonsamdi im Ardenwald, wenn Ihr zurückkommt.", sourceObjective = "Begebt Euch zum Schlund, um den verlorenen wilden Gott aus dem Ardenwald zu finden.", completion = "Alles, was ich als Schattenjäger trainiert hab, hat zu diesem Moment geführt.\n\nGeister im Schlund aufspür'n un' sie vor ewiger Folter retten...", sourceObjectiveStatus = "unverified-source-field" }
quests[59808] = { id = 59808, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Losgeschmuddelt" }
quests[59809] = { id = 59809, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Andren Seite", description = "Hey, {name}... Ich bin's, Euer alter Freund Bwonsamdi!\n\nHab gehört, Ihr treibt Euch jetz' für die Winterkönigin rum. Scheint, Ihr macht Euch 'nen mächtig groß'n Namen!\n\nDer Ardenwald is' in großer Gefahr, aber die Winterkönigin... na ja, sie is' einfach zu stolz, mit dem alt'n Bwonsamdi zu red'n.\n\nIhr wollt den Ardenwald rett'n? Dann besucht mich auf der Andren Seite.\n\nIch werd' auf Euch wart'n...", sourceObjective = "Reist mit dem Totenstein zur Andren Seite.", completion = "Willkommen auf der Andren Seite!\n\nUnd, was meint Ihr? Gefällt's Euch bei mir?", sourceObjectiveStatus = "unverified-source-field" }
quests[59811] = { id = 59811, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Große Inventur", description = "Dunkle Mächte sind am Werk, {class}.\n\nWenn Loas auf Azeroth sterb'n, geh'n sie für ihre Wiedergeburt in den Ardenwald. Aber jetz' sind 'n paar der Loa, die im Ardenwald schlaf'n, verschwund'n!\n\nDa muss jemand mit richtig viel Macht hintersteck'n un' sie der Winterkönigin unter der Nase wegschnappen...\n\nDer alte Bwonsamdi kann nich' zulassen, dass Loa aus'm Ardenwald verschwind'n. Das könnt' ich eines Tages sein! Nee, nee... Dem machen wir 'n Ende!\n\nZurück in den Ardenwald mit Euch... und sucht die verschwund'nen Loa.", sourceObjective = "Sucht in den Ruhigen Teichen nach den verschwundenen Loakapseln.", progress = "Im Ardenwald sind dunkle Mächte am Werk...", completion = "Hakkar und Dambala sind also verschwund'n? Hmmm... Dann find'n wir mal besser raus, wo sie sind!", sourceObjectiveStatus = "unverified-source-field" }
quests[59812] = { id = 59812, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Spur", description = "Ich hab 'n ungutes Gefühl deswegen, Mann!\n\nWildsamen verschwind'n nich' einfach... schon gar nich', wenn 'n mächtiger Loa da drin is'! Sogar so faule Äpfel wie Hakkar und Dambala werd'n von der Winterkönigin beschützt. Irgendwer... oder irgendwas... muss sie geklaut hab'n!\n\nAber wieso? Die waren nich' mal kurz vor der Wiedergeburt...\n\nDurchsucht das Gebiet und seht, ob Ihr 'ne Spur findet. Vermisste Loa sin' schlecht fürs Geschäft und Bwonsamdi hat schon genug Ärger mit dem Boss!", sourceObjective = "Sucht nach Hinweisen auf die vermissten Loa.", progress = "Hakkar und Dambala sind beide gleichzeitig verschwund'n? Oh, ich hab 'n ungutes Gefühl dabei...", completion = "Die Spuren führ'n in den Hain da vorn. Ich hab so das Gefühl, dass Hakkar und Dambala irgendwo in der Nähe sin'.", sourceObjectiveStatus = "unverified-source-field" }
quests[59813] = { id = 59813, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diener von Mueh'zala", description = "Das sin' alle Anhänger von Mueh'zala! Ich hätt' wiss'n müssen, dass er hinter all dem steckt.\n\nMueh'zala ist der Loa des Todes von vor langer Zeit. Er war es, der den alten Bwonsamdi aufgezogen un' mich zum Loa gemacht hat.\n\nDas war, bevor seine Gläubigen ihm den Rücken kehrt'n. Er war schon immer gierig... aber das hier...\n\nDiesmal is' Mueh'zala zu weit gegang'n! Wir müssen ihn aufhalten, oder er wird alle Loa im Ardenwald an sich reiß'n!", sourceObjective = "Besiegt Hohepriester Rakazodu und 8 Einheiten von Mueh'zalas Streitkräften.", completion = "Gut gemacht! Aber es is' noch lange nich' vorbei...", sourceObjectiveStatus = "unverified-source-field" }
quests[59815] = { id = 59815, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestohlene Loa", description = "Hakkar und Dambala sin' irgendwo im Hain.\n\nWir müssen uns beeil'n und rausfind'n, was Mueh'zala plant. Auf Azeroth war'n die beiden ziemlich mächtige Loa... mächtig und böse. Wer weiß, was Mueh'zala mit denen vorhat!\n\nDurchsucht das Geistertal. Treibt die verscholl'nen Loa auf und findet raus, was Mueh'zala vorhat!", sourceObjective = "Findet Hakkar den Seelenschinder und Dambala.", progress = "Wir müss'n wissen, was mit den vermissten Loa passiert!", completion = "Jetzt macht das alles Sinn. Mueh'zala entzieht den anderen Wildsamen Anima, damit er Dambala und Hakkar vorzeitig aufweck'n kann.\n\nDie Winterkönigin muss das erfahr'n, bevor es zu spät ist...", sourceObjectiveStatus = "unverified-source-field" }
quests[59817] = { id = 59817, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Winter naht", description = "Der Boss stellt wohl 'ne Armee schrecklicher Loa zusammen. Hakkar und Dambala sin' vielleicht nur der Anfang. Wie is' der Boss so stark geword'n? Ich hab noch nie geseh'n, dass er so 'ne Macht benutzt...\n\nDie Winterkönigin mag Bwonsamdi nich', aber wir brauch'n ihre Hilfe, um Mueh'zala aufzuhalt'n.\n\nIhr versteht Euch doch mit der Königin, oder? Wenn sie bereit is', ihre Truppen zusammenzuruf'n, könnten wir Mueh'zala vielleicht aufhalt'n, bevor es zu spät is'.\n\nGeht zum Herz des Waldes und sprecht mit der Königin. Sie is' jetz' unsre einzige Hoffnung.", sourceObjective = "Erhaltet eine Audienz bei der Winterkönigin.", progress = "Wir müssen die Winterkönigin davon überzeug'n, sich mit uns gegen Mueh'zala zusammenzutun...", completion = "Ich bin eigentlich nicht darauf erpicht, Bwonsamdi irgendwelche Gefallen zu erweisen, aber Mueh'zalas Taten können nicht unbeachtet bleiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[59818] = { id = 59818, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wilde Jagd zusammenrufen", description = "So ungern ich Bwonsamdi helfen möchte, Mueh'zala muss für seine Verbrechen zur Rechenschaft gezogen werden.\n\nWir werden seine Anbeter ausrotten und sie aus dem Wald vertreiben, bevor sie noch mehr Schaden anrichten.\n\nRuft die Haine zusammen und versammelt die Wilde Jagd. Der Ardenwald braucht seine Beschützer.\n\nEilt Euch, <Jäger/Jägerin>.", sourceObjective = "Ruft die Wilde Jagd nach Tirna Noch im Ardenwald zusammen.", completion = "Ihr kommt gerade rechtzeitig. Die Wilde Jagd kämpft verbissen gegen Mueh'zalas Streitkräfte.", sourceObjectiveStatus = "unverified-source-field" }
quests[59819] = { id = 59819, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Wald säubern", description = "Die Winterkönigin hat uns befohlen, Mueh'zalas Streitkräfte aus dem Ardenwald zu vertreiben.\n\nDas wird kein leichter Kampf. Die Armee des Todesloas ist stark, und einige unserer Jäger wurden schwer verletzt.\n\nKönnen wir darauf zählen, dass Ihr das Blatt zu unseren Gunsten wendet, {name}?\n\nHelft unseren gefallenen Verbündeten und bezwingt Mueh'zalas Diener!", sourceObjective = "Helft der Wilden Jagd in ihrem Kampf gegen Mueh'zalas Streitkräfte.", completion = "Die Wilde Jagd wird den Rest von ihnen aus dem Wald vertreiben. Gut gemacht, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[59821] = { id = 59821, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bericht an die Königin", description = "Mueh'zalas Streitkräfte sind besiegt, und es ist nur eine Frage der Zeit, bis die Wilde Jagd sie vollständig aus dem Ardenwald vertreibt.\n\nAber etwas sagt mir, dass der Kampf zwischen Bwonsamdi und Mueh'zala noch lange nicht vorbei ist. Diese unheimliche kleine Maske ist verstummt...\n\nIhr solltet ins Herz des Waldes zurückeilen und der Winterkönigin Bericht erstatten. Sie wird entscheiden, was wir als Nächstes tun.", sourceObjective = "Sprecht mit der Winterkönigin.", completion = "Eine willkommene Nachricht. Ich werde die Übergriffe Mueh'zalas nicht so bald vergessen.", sourceObjectiveStatus = "unverified-source-field" }
quests[59822] = { id = 59822, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Spur eines wilden Gottes", description = "Das hier is' ein finstrer Ort, {name}. Wir müss'n den Geist ausfindig machen, der hier gefangen is'.\n\nIch glaub', ich kann seine Spur aufnehmen... aber mehr kann dieser alte Schattenjäger nich' tun.\n\nWenn ich versuch', mit Euch zu kämpfen, könnten die Fäden reißen, die mich an Azeroth binden. Dann sitz' ich auch hier fest.\n\nKommt schon. Wir sollt'n uns lieber auf den Weg mach'n.", sourceObjective = "Spürt die verlorenen Geister aus dem Ardenwald auf.", completion = "Wir sin' hier noch nich' fertig. Hier sin' Loa gefangen!", sourceObjectiveStatus = "unverified-source-field" }
quests[59824] = { id = 59824, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rettung der Loa", description = "Wir sind wegen Ashamane hier, aber ich hab das Gefühl, dass da vorn Loa gefoltert werd'n. Drei, wenn ich richtig lieg'.\n\nIch weiß nich', wer sie sind, aber sie gehör'n nich' in den Schlund.\n\nWir müssen sie auch in den Ardenwald zurückbring'n!", sourceObjective = "Findet und rettet die drei im Schlund gefangenen Loa.", completion = "Rezan braucht uns!", sourceObjectiveStatus = "unverified-source-field" }
quests[59825] = { id = 59825, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Samenjagd" }
quests[59826] = { id = 59826, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wettet auf Euch selbst", description = "<Schlundgänger/Schlundgängerin>, wir schätzen Euch... Aber Ihr werdet verlieren. Jeder weiß, dass Ihr Euch in der Arena nicht messen könnt. \n\nDie gesamte Herausfordererpromenade weiß es, die Mittler in Oribos wissen es, sogar Zo'umlo weiß es.\n\nIch habe einen besonderen Herausforderer mitgebracht, um das deutlich zu machen. Stellt Euch Herrin Dyrax im Theater der Schmerzen und beweist uns das Gegenteil... oder, dass wir recht haben.\n\nWir werden Wetten abgeben, enttäuscht uns also nicht.", sourceObjective = "Besiegt Herrin Dyrax im Theater der Schmerzen, wenn sie hereinkommt.", progress = "Was habt Ihr bewiesen?", completion = "Eure Leistung hat mir hübsch Gewinn eingebracht... Zo'umlo hat schlecht gewettet.", sourceObjectiveStatus = "unverified-source-field" }
quests[59827] = { id = 59827, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wettet auf Euch selbst", description = "<Schlundgänger/Schlundgängerin>, wir schätzen Euch... Aber Ihr werdet verlieren. Jeder weiß, dass Ihr Euch in der Arena nicht messen könnt. \n\nDie gesamte Herausfordererpromenade weiß es, die Mittler in Oribos wissen es, sogar Zo'umlo weiß es.\n\nIch habe einen besonderen Herausforderer mitgebracht, um das deutlich zu machen. Stellt Euch Devmorta im Theater der Schmerzen und beweist uns das Gegenteil... oder, dass wir recht haben.\n\nWir werden Wetten abgeben, enttäuscht uns also nicht.", sourceObjective = "Besiegt Devmorta im Theater der Schmerzen, wenn er hereinkommt.", completion = "Eure Leistung hat mir hübsch Gewinn eingebracht... Zo'umlo hat schlecht gewettet.", sourceObjectiveStatus = "unverified-source-field" }
quests[59828] = { id = 59828, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wettet auf Euch selbst", description = "<Schlundgänger/Schlundgängerin>, wir schätzen Euch... Aber Ihr werdet verlieren. Jeder weiß, dass Ihr Euch in der Arena nicht messen könnt. \n\nDie gesamte Herausfordererpromenade weiß es, die Mittler in Oribos wissen es, sogar Zo'umlo weiß es.\n\nIch habe einen besonderen Herausforderer mitgebracht, um das deutlich zu machen. Stellt Euch Ti'or im Theater der Schmerzen und beweist uns das Gegenteil... oder, dass wir recht haben.\n\nWir werden Wetten abgeben, enttäuscht uns also nicht.", sourceObjective = "Besiegt Ti'or im Theater der Schmerzen, wenn sie hereinkommt.", progress = "Was habt Ihr bewiesen?", completion = "Eure Leistung hat mir hübsch Gewinn eingebracht... Zo'umlo hat schlecht gewettet.", sourceObjectiveStatus = "unverified-source-field" }
quests[59836] = { id = 59836, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Längst errungene Siege" }
quests[59837] = { id = 59837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeit für die Lebenden", description = "Ihr scheint Euch zu wundern, woher wir die ganzen Herausforderer für diese Arena bekommen.\n\nWir suchen zahllose Reiche nach Gegnern ab, um den Maldraxxi Kampferfahrungen aus erster Hand zu liefern.\n\nZurzeit bemühe ich mich um einen neuen Kämpfer und damit eine lukrative Wettgelegenheit.\n\nWürdet Ihr unser Portal nutzen und Zo'umlo helfen, Khogov den Ausmerzer einzufangen? Ihr werdet selbstverständlich angemessen entschädigt.", sourceObjective = "Zerschmetterten Hain abgesichert und Khogov den Ausmerzer gefangen.", completion = "Die Teilnahme in der Arena ist eine Möglichkeit, sich in dieser Unternehmung einzubringen. Aber es gibt noch viele andere Aufgaben zu erledigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[59838] = { id = 59838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsmaschinen der Geißel", description = "Die Kriegsmaschinen der Geißel erschweren es, an Boden zu gewinnen. Sie müssen unsere höchste Priorität sein.\n\nObwohl sie gut geschützt sind, müssen wir sie zerstören, um den Weg für unsere Bodentruppen freizumachen und ihnen eine Angriffsmöglichkeit zu verschaffen.\n\nBringt diese Sprengladungen unter den Kriegsmaschinen an und säubert den Bereich.", sourceObjective = "Zerstört 5 Kriegsmaschinen der Geißel im Großbrand.", completion = "Gute Arbeit, {name}.\n\nJetzt können unsere Streitkräfte vorstoßen, ohne die Waffen des Feindes fürchten zu müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[59839] = { id = 59839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WARNUNG: Dies ist nur ein Test!", description = "Wo manche ein Problem sehen, sehe ich eine Chance. Dieses Geißelfiasko verlangt nach einer kreativen Lösung!\n\nHier ist meine \"Geheimwaffe\"!\n\nGesteuert von keinem Geringeren als meinem sorgfältig synchronisierten Steuerungsgerät, oder kurz S.S.S.G.!\n\nHmm, an dem Namen muss ich wohl noch arbeiten.\n\nIhr seht es als <Erster/Erste>, also dürft Ihr es auch zuerst ausprobieren. Keine Sorge, es ist wahrscheinlich sicher.\n\nViel Glück!", sourceObjective = "Testlauf von Fizzix Sprengbolz' \"Geheimwaffe\" in Todessprechers Wacht erfolgreich abgeschlossen.", progress = "Und, wie geht's?", completion = "Junge, Junge! Habt Ihr die Gesichter gesehen?\n\nGut, manche haben nicht wirklich Gesichter, aber Ihr wisst schon... ihre Kiefer und all das. Ha!\n\nDas war großartig. Die Möglichkeiten sind endlos!", sourceObjectiveStatus = "unverified-source-field" }
quests[59840] = { id = 59840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Göttliche Dankbarkeit", description = "Vielen Dank, dass Ihr meine Macht und meine Tatkraft wiederhergestellt habt.\n\nMein Weg wird mich jetzt zurück zu meinem Volk führen, aber es ist nur recht und billig, dass Ihr für Eure Bemühungen belohnt werdet.", sourceObjective = "Nehmt den von der Gottheit angebotenen Segen an.", sourceObjectiveStatus = "unverified-source-field" }
quests[59846] = { id = 59846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des einen Freud, des Sünders Leid", description = "Oh, hallo, <Sterblicher/Sterbliche>. Ihr habt wirklich das Talent, immer zum günstigsten Zeitpunkt einzutreffen. Ich frage mich, was Zuchtmeister Matyas von Euch will. Ist schon seltsam.\n\nWas mich betrifft, hat Matyas schon wieder meinen Sündenstein gegen mich eingesetzt. Ich war schon wütend darüber, dass er mich eingesperrt hat, und ich kann Euch garantieren, dass dieser letzte Angriff nicht folgenlos bleiben wird. Aber solange er meinen Sündenstein hat, kann ich nicht direkt gegen ihn vorgehen. Wir müssen also Abhilfe schaffen.\n\nIhr befragt die Arbeiter und ich werde dieses Tagebuch lesen, während ich meine Kräfte sammle.", sourceObjective = "Entdeckt die Geheimnisse um das Vorgehen von Zuchtmeister Matyas im Fresserdickicht.", progress = "Habt Ihr etwas Nützliches herausgefunden?", completion = "Ah. Schade, dass keine davon mir gehören. Aber sie könnten dennoch nützlich sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[59848] = { id = 59848, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teegeplauder: Theotar" }
quests[59850] = { id = 59850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teegeplauder: Vulca" }
quests[59851] = { id = 59851, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu Eis erstarrt", description = "Der Atem eines Frostwyrms kann sogar den größten Gegner sofort einfrieren. Das mussten unsere Streitkräfte leider am eigenen Leibe erfahren.\n\nIhr Vorstoß auf die Zitadelle ist zum Stillstand gekommen. Ich fürchte, dass wir unsere Stellung einbüßen, wenn wir nicht schnell handeln.\n\nNehmt diesen Trank und befreit unsere Streitkräfte damit von ihren eisigen Fesseln. Möge das Licht mit Euch sein.", sourceObjective = "Rettet 12 eingefrorene Verbündete beim Hof der Knochen.", completion = "Ausgezeichnete Arbeit, {name}. Wir kümmern uns darum, dass sie sich in Sicherheit erholen.", sourceObjectiveStatus = "unverified-source-field" }
quests[59852] = { id = 59852, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teegeplauder: Gubbins und Tubbins" }
quests[59853] = { id = 59853, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teegeplauder: Verlorene Sibylle" }
quests[59855] = { id = 59855, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signifikante Spiegelstörungen" }
quests[59856] = { id = 59856, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rezan, Loa der Könige", description = "Rezan is 'n mächtiger Loa, der sehr wichtig für die Zandalari is'.\n\nWir müss'n ihn rett'n... aber diese Kreatur gibt 'ne Todesbarriere ab. Da is' kein Reinkommen.\n\nEs sei denn... ich nehm' etwas von meiner Anima und schirm' Euch vor ihrer Magie ab.\n\nIhr müsst schnell handeln und das Monster töt'n, das Rezan auslaugt. Meine Anima hält nich' ewig.\n\nIhr sagt, wenn Ihr bereit seid.", sourceObjective = "Nehmt etwas von Vol'jins Anima an, um Euch zu schützen, und tötet dann Exhaurbius, um Rezan zu retten.", progress = "Wir müss'n Rezan rett'n!", completion = "Ich spür' Rezans Essenz in mir... er vertraut mir 'n großes Geschenk an.\n\nEgal, was als nächstes kommt, ich werd' ihn nich' enttäuschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[59862] = { id = 59862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Retter der verlorenen Seelen", sourceObjective = "Geht mit der Wächterin zum Hain.", progress = "Unsere Wege kreuzen sich. Gehen wir gemeinsam.", completion = "Eure Anwesenheit wärmt den Hain.\n\nJetzt lernen und gedeihen wir.", sourceObjectiveStatus = "unverified-source-field" }
quests[59863] = { id = 59863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfnullifizierer 07-X", description = "Während alle damit beschäftigt sind, unsere Gegner mit Schwert und Magie abzuwehren, versuchen wir etwas anderes.\n\nHier ist meine neueste Erfindung, der Kampfnullifizierer 07-X!\n\nMit diesem Gerät ist der Gegner keiner mehr!\n\nIch habe die exakten Energiemodulatorkalkulationen noch nicht zur Hand, aber es funktioniert. Meistens.\n\nErst einmal müssen wir etwas Energie von unseren Gegnern borgen, um es zum Laufen zu bringen.\n\nNa los. Ladet es auf und probiert es aus!", sourceObjective = "Ladet das Energieeindämmungsmodul auf, um 5 Gegner mit dem Kampfnullifizierer 07-X bei Sindragosas Sturz zu pulverisieren.", progress = "Wie läuft's?", completion = "Wow! Das war ein Kracher, was?", sourceObjectiveStatus = "unverified-source-field" }
quests[59865] = { id = 59865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glimmerflug", description = "Wie spannend!\n\nKommt, ein weiterer Test ist angebracht. Ich kann es kaum erwarten!", sourceObjective = "Beobachtet Kowalskos' Testflug.", completion = "Ich habe es geschafft! Ich bin geflogen!\n\nIch habe Änderungen, die ich vornehmen kann. Hier, nehmt diese Glimmerfliegen als Dank. Ich werde noch mehr sammeln!", sourceObjectiveStatus = "unverified-source-field" }
quests[59866] = { id = 59866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Getrennte Wege", description = "Ich hab' keine Ahnung, was dem alten Vol'jin blüht... aber es wartet auf mich im Ardenwald.\n\nAshamane, Hir'eek, Shadra... die gehör'n auch dahin.\n\nWir sollt'n lieber dahingeh'n. Was ich vom Schlund geseh'n habe, reicht für den Rest aller Zeiten.", sourceObjective = "Bringt die verlorenen Loa und Vol'jin zur Winterkönigin im Ardenwald.", completion = "Es freut mich zu wissen, dass die im Schlund verschollenen Geister wieder in Sicherheit sind.\n\nNiemand kann sagen, was das Schicksal für Vol'jin bereithält. Der Weg, den er eingeschlagen hat, ist noch nie zuvor von einer sterblichen Seele beschritten worden.\n\nAber was immer ihn erwartet, seid gewiss, dass Eure Bemühungen es möglich gemacht haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[59867] = { id = 59867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Gutachter Vix", description = "Für die Nichtzahlung von Schulden aus verlorenen Wetten, Diebstahl von Arenaeigentum und für die Tötung eines bevollmächtigten Schuldeneintreibers. Hiermit wird jede notwendige Gewalt bei einer Konfrontation mit Vix gebilligt.\n\nBesondere Warnung: Haltet Ausschau nach zahlreichen Mitarbeitern, die eine gewalttätige Haltung gegenüber Fremden an den Tag gelegt haben.\n\nDie Eliminierung dieses Straftäters hat höchste Priorität.", sourceObjective = "Beseitigt Gutachter Vix", completion = "Ausgezeichnete Arbeit, Schlundgänger. Ich werde Zo'umlo entsenden, um unser gestohlenes Eigentum zurückzuholen.", sourceObjectiveStatus = "unverified-source-field" }
quests[59868] = { id = 59868, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angebot der Freiheit", description = "Genau wie in meinem Fall werden einige Dornfluchventhyr, denen Ihr begegnet, dazu gezwungen worden sein, Matyas zu dienen. Sie wollen wahrscheinlich gar nicht gegen Euch kämpfen, aber sie haben keine Wahl. Wenn sie verletzt werden, könnten sie vielleicht innehalten, um zu sehen, ob einer der Sündensteine, die Ihr geborgen habt, ihnen gehört.\n\nBefreit alle, die Ihr könnt. Sündensteine zu verwenden, um andere zu nötigen, ist einfach nicht fair.", sourceObjective = "Schwächt die Dornfluchventhyr und bietet ihnen einen Sündenstein an.", completion = "Ihr habt heute Freunde dazugewonnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[59871] = { id = 59871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Katalysiert das", description = "Der Hain wird mächtiger, und die Geister, die er beherbergt, sollen es ebenfalls werden.\n\nIhr habt ganz allein einen Geist bis zur Wiedergeburt gepflegt. Jetzt müsst Ihr lernen, mit Katalysatoren umzugehen.\n\nWenn sie in der Nähe eines Wildsamens gepflanzt werden, verleihen Katalysatoren dem schlummernden Geist eine Kraft, die über das hinausgeht, was er zu Lebzeiten kannte. Kraft, die er bei der Wiedergeburt behält.\n\nKatalysatoren sind etwas Besonderes und selten, aber ich habe hier einen, den Ihr verwenden könnt. Überall in den Schattenlanden könnt Ihr noch mehr finden.\n\nPflanzt den Katalysator einfach ein und werdet Zeuge des Potenzials, das er birgt.", sourceObjective = "Verwendet den Katalysator auf dem Katalysatorfeld.", completion = "So viele Geschenke die Natur macht, so viele Geheimnisse birgt sie auch.", sourceObjectiveStatus = "unverified-source-field" }
quests[59872] = { id = 59872, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie man einen Gott rettet", description = "Viele sterbliche Seelen leiden im Schlund. Genauso wie viele Geister der Natur.\n\nDer Kerkermeister schlägt Wunden, die nicht allein durch Anima geheilt werden können. Geister, die aus seinen Klauen befreit wurden, müssen neu gepflanzt werden und brauchen spezielle Aufmerksamkeit.\n\nDiese Wildsamen sind etwas Besonderes, genauso wie dieser Hain. In ihnen schlummert die Hoffnung, dass auch der schwächste Geist wiedergeboren werden kann.\n\nEiner wie dieser hier. Bettet diesen Geist in einem Wildsamen zur Ruhe und lasst seine Wiedergeburt beginnen.", sourceObjective = "Legt den Seelensamen in den Wildsamen.", completion = "Eure Fertigkeiten schlagen Wurzeln, Schlundgänger.", sourceObjectiveStatus = "unverified-source-field" }
quests[59873] = { id = 59873, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen Gott begrüßen", description = "Der Augenblick der Wiedergeburt des Geists ist nahe. Ein Schicksal, das der Schlund schon fast besiegelt hatte, aber das durch Hain und Hüter abgewendet wurde.\n\nDie Zeit tut dem Geist gut. Legt Eure Hand auf den Wildsamen und erweckt ihn, sobald genug Zeit verstrichen ist.", sourceObjective = "Wartet ab, bis der Geist die Inkubation abgeschlossen hat, dann öffnet den Wildsamen.", completion = "Und so wird ein Gott durch die Hand eines Sterblichen wiedergeboren.\n\nIhr wurdet mit Dankbarkeit begrüßt, ja? Und vielleicht auch mit Verwunderung.", sourceObjectiveStatus = "unverified-source-field" }
quests[59874] = { id = 59874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schlund", sourceObjective = "Sprecht mit Bolvar in Oribos.", completion = "Gibt es Neuigkeiten aus Maldraxxus, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[59876] = { id = 59876, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einsatzberichte", description = "Die Geißel kann jederzeit und überall zuschlagen.\n\nUm dieser Unvorhersehbarkeit zuvorzukommen, hat der Argentumkreuzzug Schlüsselpunkte entlang der südlichen Straße Richtung Osten gesichert. Allerdings habe ich noch keine Berichte von unseren Spähern erhalten.\n\nAngesichts der Unberechenbarkeit der Angriffe befürchte ich das Schlimmste.\n\nBegebt Euch zur Straße und überprüft die Außenposten. Ich erwarte einen umfassenden Bericht bei Eurer Rückkehr.\n\nMöge das Licht mit Euch sein, {name}.", sourceObjective = "Sammelt Berichte von Offizieren im Wald von Elwynn, im Rotkammgebirge und dem Dämmerwald.", progress = "Gregor hat Euch geschickt?", completion = "Es ist schlimmer, als wir dachten.\n\nKommandant Gregor muss vom wahren Ausmaß der Rückkehr der Geißel unterrichtet werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[59877] = { id = 59877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Botschaft aus Eiskrone", description = "Unsere Streitkräfte in Nordend haben Bericht erstattet. Justiziarin Treuherz erbittet unsere sofortige Hilfe.\n\nAls <erfahrener/erfahrene:c> {class} bitte ich Euch, Euch darum zu kümmern.\n\nWir können die Dringlichkeit dieses Ersuchens nicht ignorieren, auch wenn es bedeutet, den Schrecken von Eiskrone trotzen zu müssen.\n\nIch weiß, dass Ihr um die Sicherheit von allen hier fürchtet. Ich werde unsere Anstrengungen hier weiter koordinieren und Verstärkung rufen.\n\nMöge das Licht mit Euch sein, {name}.", sourceObjective = "Meldet Euch bei Justiziarin Mariel Treuherz am Argentumturnierplatz in Eiskrone.", completion = "Ihr kommt genau zur rechten Zeit. Kommandant Gregor hat Euch in den höchsten Tönen gelobt.", sourceObjectiveStatus = "unverified-source-field" }
quests[59878] = { id = 59878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu viele Welpen", description = "Wir können nicht darauf hoffen, diese Position zu halten, wenn die Frostwyrms die Himmel über uns durchstreifen.\n\nKultisten haben in der Nähe Welpen von den Toten erweckt. Je mehr wir beseitigen, desto weniger Monstrositäten überziehen unsere Streitkräfte mit tödlichem Eis.\n\nMacht ihren Anstrengungen ein Ende.", sourceObjective = "Tötet 4 Wyrmwiedererwecker und 12 Frostbrutwelpen bei Sindragosas Sturz.", completion = "Gute Arbeit, {name}. Das sollte uns kurzen Aufschub gewähren.", sourceObjectiveStatus = "unverified-source-field" }
quests[59879] = { id = 59879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsere Sache", description = "Au'narim ist die beste Mittlerin hier. Sie versorgt uns mit exotischen Kreaturen, die wir in der Arena bekämpfen können.\n\nIhr seid ihr aufgefallen und sie will Euch treffen!\n\nDas ist sehr wichtig. Die Unterstützung eines Mittlers könnte Euch eine Einladung zum Wettbewerb verschaffen!", sourceObjective = "Trefft Euch mit Au'narim.", completion = "Ihr müsst einer dieser Fremdlinge sein, von denen ich so viel höre.", sourceObjectiveStatus = "unverified-source-field" }
quests[59882] = { id = 59882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sichere Wette", description = "Ihr scheint großes Profitpotenzial zu haben.\n\nEs gibt viele interessierte Parteien, die auf Eure Leistung im Theater der Schmerzen wetten wollen.\n\nGeht, Louison wird Eure Teilnahme arrangieren.", sourceObjective = "Trefft Euch mit Louison", sourceObjectiveStatus = "unverified-source-field" }
quests[59894] = { id = 59894, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Goldene Dämmerung", description = "Die Machenschaften des Krieges beginnen. Gharmals Verbrechen sind jetzt für die ganzen Schattenlande erkennbar.\n\nDie Bastion verlangt nach Rache und wir werden sie ihnen zuteilwerden lassen. Nur mit vereinten Kräften werden wir die Konstrukte ein für alle Mal besiegen.\n\nTrefft Draka auf der Warte. Eure Anwesenheit wird helfen, ein Übereinkommen zu erzielen.", sourceObjective = "Teleportiert zur Warte und trefft Euch mit Draka.", completion = "Eine Allianz ist gesichert. Jetzt planen wir den Angriff.", sourceObjectiveStatus = "unverified-source-field" }
